"""Independent teaching narratives and complete worked derivations for 22 sets."""
from final_content import frac as F, unit as U

DEPTH = {}
def lesson(n, intuition, derivation, traps, engineering, checkpoint, assumptions):
    DEPTH[n] = dict(intuitionParagraphs=intuition, derivation=derivation,
                    examTraps=traps, engineeringParagraphs=engineering,
                    checkpoint=checkpoint, assumptions=assumptions)

lesson(1, [
 'แรง 5 N ทางตะวันออกกับแรง 5 N ทางเหนือมีขนาดเท่ากัน แต่ทำให้วัตถุเคลื่อนไปต่างทาง เวกเตอร์จึงต้องบันทึกทั้งขนาดและทิศ เลือกฐานเหมือนเลือกไม้บรรทัดสามแนว เวกเตอร์จริงไม่เปลี่ยนเมื่อหมุนไม้บรรทัด มีเพียงตัวเลของค์ประกอบที่เปลี่ยน',
 'ผลคูณจุดถามว่าอีกเวกเตอร์ช่วยไปตามทิศที่สนใจเท่าใด จึงเป็นการฉายและให้สเกลาร์ ผลคูณไขว้ถามถึงพื้นที่ที่ลูกศรสองอันกางออก และแนวตั้งฉากที่กำหนดด้วยมือขวา ความหมายทั้งสองต่างกันตั้งแต่ก่อนเริ่มคำนวณ'], [
 ('สูตรตั้งต้นของฐานตั้งฉาก', '<b>A</b> = Σ<sub>i=x,y,z</sub><em>A</em><sub>i</sub>'+U('i')+'; '+U('i')+' • '+U('j')+' = δ<sub>ij</sub>', 'δ เท่ากับหนึ่งเมื่อฐานเดียวกันและศูนย์เมื่อคนละฐาน เป็นเงื่อนไขที่ใช้ในทุกการกระจายต่อไป'),
 ('ฉายองค์ประกอบโดยไม่เดาทิศ', '<b>A</b> • '+U('x')+' = <em>A</em><sub>x</sub>(1) + <em>A</em><sub>y</sub>(0) + <em>A</em><sub>z</sub>(0) = <em>A</em><sub>x</sub>', 'คูณจุดทั้งสองข้างของสูตรตั้งต้น ฐานที่ตั้งฉากกันตัดพจน์อื่นทิ้ง'),
 ('กระจายขนาดกำลังสอง', '|<b>A</b>|² = <b>A</b> • <b>A</b> = Σ<sub>i</sub>Σ<sub>j</sub><em>A</em><sub>i</sub><em>A</em><sub>j</sub>δ<sub>ij</sub> = <em>A</em><sub>x</sub>² + <em>A</em><sub>y</sub>² + <em>A</em><sub>z</sub>²', 'พจน์ข้ามแกนเป็นศูนย์ เหลือเฉพาะผลคูณแกนเดียวกัน จึงได้พีทาโกรัสสามมิติ'),
 ('หาเวกเตอร์หน่วยของทิศใดก็ได้', U('A')+' = '+F('<b>A</b>','|<b>A</b>|')+'; |'+U('A')+'|² = '+F('|<b>A</b>|²','|<b>A</b>|²')+' = 1', 'หารทุกองค์ประกอบด้วยขนาดเดียวกัน เปลี่ยนความยาวให้เป็นหนึ่งโดยไม่เปลี่ยนทิศ ใช้ไม่ได้เมื่อเวกเตอร์เป็นศูนย์'),
 ('เชื่อมการฉายกับมุม', '<b>A</b> • <b>B</b> = <em>A</em><sub>x</sub><em>B</em><sub>x</sub> + <em>A</em><sub>y</sub><em>B</em><sub>y</sub> + <em>A</em><sub>z</sub><em>B</em><sub>z</sub> = |<b>A</b>| |<b>B</b>| cos θ', 'ส่วนที่ B ฉายบนแนว A ยาว |B|cosθ แล้วคูณขนาด A เครื่องหมายลบหมายถึงฉายสวนทิศ'),
 ('กระจายผลคูณไขว้ตามฐาน', '<b>A</b> × <b>B</b> = (<em>A</em><sub>y</sub><em>B</em><sub>z</sub>−<em>A</em><sub>z</sub><em>B</em><sub>y</sub>)'+U('x')+' + (<em>A</em><sub>z</sub><em>B</em><sub>x</sub>−<em>A</em><sub>x</sub><em>B</em><sub>z</sub>)'+U('y')+' + (<em>A</em><sub>x</sub><em>B</em><sub>y</sub>−<em>A</em><sub>y</sub><em>B</em><sub>x</sub>)'+U('z'), 'ใช้ x×y=z, y×z=x, z×x=y พจน์ฐานเดียวกันเป็นศูนย์และเมื่อสลับลำดับต้องติดลบ'),
 ('ตรวจด้วยตัวอย่างที่คำนวณในใจได้', '<b>A</b>=3'+U('x')+'+4'+U('y')+'; <b>B</b>=2'+U('z')+'<br>|<b>A</b>|=5; <b>A</b> • <b>B</b>=0; <b>A</b> × <b>B</b>=8'+U('x')+'−6'+U('y')+'; |<b>A</b> × <b>B</b>|=10', 'เวกเตอร์ตั้งฉากกันจึง dot เป็นศูนย์และพื้นที่เท่ากับ 5×2 ตรวจด้วยการคูณผลลัพธ์กับ A และ B จะได้ศูนย์ทั้งคู่')],
 ['ห้ามบวกขนาดแทนองค์ประกอบเมื่อแรงไม่ขนานกัน', 'สลับ A×B เป็น B×A ต้องกลับเครื่องหมายทั้งเวกเตอร์', 'เวกเตอร์หน่วยไม่มีหน่วย แต่ขนาดผลคูณต้องรักษาหน่วยของเวกเตอร์ต้นทาง'],
 ['งานของแรงเป็นผลคูณจุดกับการกระจัด เพราะแรงตั้งฉากเส้นทางไม่ทำงาน ส่วนแรงบิดเป็นผลคูณไขว้ของแขนแรงกับแรง จึงบอกแกนหมุนของโรเตอร์ได้', 'ต่อไปแรงบนตัวนำกระแสในสนามแม่เหล็กจะใช้ผลคูณไขว้ ขณะที่การนับฟลักซ์ผ่านหน้าขดลวดใช้ผลคูณจุด ทักษะเลือกตัวดำเนินการจึงสำคัญกว่าจำสูตร'],
 'ถ้าหมุนแกนพิกัด 30° ขนาดเวกเตอร์จริงต้องเปลี่ยนหรือไม่? อธิบายด้วยนิยามผลคูณจุด', 'ใช้ฐานฉากที่มีขนาดหนึ่งและจัดลำดับตามมือขวา')

lesson(2, [
 'รอบลวดตรงหรือแกนเครื่องจักร รูปร่างซ้ำเดิมทุกมุม จึงสะดวกที่จะวัดระยะออกจากแกนด้วย ρ แทน x และ y แต่ฐานรัศมีของคนที่อยู่คนละด้านของแกนชี้คนละทิศ ตัวเลของค์ประกอบเท่ากันจึงไม่ได้หมายถึงลูกศรฉากเท่ากัน',
 'เดินเพิ่มมุมเล็ก dϕ ที่รัศมีไกลกว่า จะเดินเป็นระยะทางมากกว่า นี่คือเหตุที่ ρ ต้องอยู่ในส่วนย่อยความยาว พื้นที่ ปริมาตร และตัวดำเนินการอนุพันธ์ ไม่ใช่ตัวประกอบที่เพิ่มมาจากการท่องจำ'], [
 ('นิยามตำแหน่งทั่วไป', '<b>r</b>(ρ,ϕ,z)=ρ cosϕ'+U('x')+'+ρ sinϕ'+U('y')+'+z'+U('z'), 'นี่คือเวกเตอร์จากจุดกำเนิดไปยังจุดสังเกต ไม่ใช่เวกเตอร์สนามที่ต้องการแปลง'),
 ('หาแนวเพิ่มรัศมี', F('∂<b>r</b>','∂ρ')+'=cosϕ'+U('x')+'+sinϕ'+U('y')+'='+U('ρ'), 'ถือมุมและความสูงคงที่แล้วดิฟเฟอเรนเชียลตามรัศมี เวกเตอร์ที่ได้มีขนาดหนึ่ง'),
 ('หาแนวเพิ่มมุมและทำให้เป็นหน่วย', F('∂<b>r</b>','∂ϕ')+'=ρ(−sinϕ'+U('x')+'+cosϕ'+U('y')+'); '+U('ϕ')+'='+F('1','ρ')+F('∂<b>r</b>','∂ϕ'), 'อนุพันธ์ตามมุมมีขนาด ρ ต้องหารออกก่อนเรียกว่าเวกเตอร์หน่วย ทิศเพิ่ม ϕ ทวนเข็มเมื่อมองจาก +z'),
 ('แปลงเวกเตอร์ด้วยการฉาย', '<em>A</em><sub>ρ</sub>=<em>A</em><sub>x</sub>cosϕ+<em>A</em><sub>y</sub>sinϕ<br><em>A</em><sub>ϕ</sub>=−<em>A</em><sub>x</sub>sinϕ+<em>A</em><sub>y</sub>cosϕ; <em>A</em><sub>z</sub> คงเดิม', 'ฉาย A บนฐานที่ตำแหน่งนั้น ใช้มุมของจุด P ที่โจทย์กำหนด ไม่ใช้มุมของลูกศรสนาม'),
 ('ดิฟเฟอเรนเชียลตำแหน่ง', 'd<b>l</b>='+U('ρ')+'dρ+ρ'+U('ϕ')+'dϕ+'+U('z')+'dz', 'กฎลูกโซ่รวมอนุพันธ์ตามพิกัดทั้งสาม ให้ด้านเล็กของกล่องโค้งยาว dρ, ρdϕ และ dz'),
 ('ประกอบผิวและปริมาตร', 'd<b>s</b><sub>ρ</sub>=ρdϕdz'+U('ρ')+'; d<b>s</b><sub>ϕ</sub>=dρdz'+U('ϕ')+'; d<b>s</b><sub>z</sub>=ρdρdϕ'+U('z')+'<br>dv=ρdρdϕdz', 'แต่ละผิวใช้ผลคูณด้านที่อยู่บนผิวนั้น ส่วนปริมาตรใช้ผลคูณทั้งสามด้าน กล่องเล็กจึงอธิบาย Jacobian ได้'),
 ('ตรวจกรณีบนแกน y บวก', 'ϕ=90° ⇒ '+U('ρ')+'='+U('y')+'; '+U('ϕ')+'=−'+U('x')+'<br>'+U('ρ')+' × '+U('ϕ')+'='+U('z'), 'ทิศสัมผัสต้องชี้ไปทาง x ลบจึงเพิ่มมุมต่อได้ ตรวจลำดับฐานด้วยมือขวา')],
 ['ใช้ atan2 เพื่อรักษาควอดรันต์; arctan(y/x) อย่างเดียวแยกด้านตรงข้ามไม่ได้', 'ห้ามลืม ρ ในวงกลมและพื้นที่หน้าตัด', 'ที่ ρ=0 มุม ϕ และฐานรัศมีไม่กำหนด ต้องพิจารณาลิมิตในฐานฉาก'],
 ['สนามรอบบัสบาร์ทรงกระบอกและสายโคแอกเชียลมีสมมาตรตรงกับฐานนี้ การเลือกวงรัศมีคงที่จะทำให้การอินทิเกรตแอมแปร์เหลือเพียงมุมเดียว', 'ในการวิเคราะห์เครื่องจักรหมุน องค์ประกอบรัศมีและสัมผัสช่วยแยกแรงกดผิวออกจากแรงที่สร้างแรงบิดได้ แม้แบบจำลองจริงจะต้องรวมวัสดุและช่องอากาศเพิ่มเติม'],
 'บนวง ρ=2 m เมื่อเพิ่มมุม 0.1 rad ระยะทางเท่าใด และฐานรัศมีเปลี่ยนหรือไม่?', 'ρ≥0 และใช้มุมเป็นเรเดียนในส่วนย่อยและอนุพันธ์')

lesson(3, [
 'ทรงกลมเหมาะกับสิ่งที่ชี้ออกจากศูนย์กลาง เช่นสนามของประจุจุด มุม θ วัดลงจากแกน +z ส่วน ϕ หมุนรอบแกน z คนที่อยู่ขั้วเหนือกับเส้นศูนย์สูตรจึงถือไม้บรรทัดรัศมีต่างทิศ แม้ระยะจากศูนย์กลางเท่ากัน',
 'เส้นละติจูดใกล้ขั้วมีรัศมีเล็กกว่าที่เส้นศูนย์สูตร เดินเพิ่ม ϕ เท่ากันจึงกินพื้นที่น้อยกว่า ตัวประกอบ sinθ ในพื้นที่ไม่ใช่เครื่องประดับของสูตร แต่เป็นขนาดวงรอบแกนที่ยุบลงใกล้ขั้ว'], [
 ('สูตรตำแหน่งก่อนแปลงฐาน', '<b>r</b>=r sinθ cosϕ'+U('x')+'+r sinθ sinϕ'+U('y')+'+r cosθ'+U('z'), 'กำหนดคอนเวนชันของมุมก่อนคำนวณ มิฉะนั้นสูตรทุกตัวอาจใช้ θ และ ϕ สลับกัน'),
 ('สร้างฐานรัศมี', U('r')+'='+F('∂<b>r</b>','∂r')+'=sinθ'+U('ρ')+'+cosθ'+U('z'), 'มองรูปในระนาบรัศมีกับ z ขนาดการฉายออกด้านข้างเป็น sinθ และตาม z เป็น cosθ'),
 ('สร้างฐานมุมขั้ว', F('∂<b>r</b>','∂θ')+'=r cosθ'+U('ρ')+'−r sinθ'+U('z')+' ⇒ '+U('θ')+'=cosθ'+U('ρ')+'−sinθ'+U('z'), 'หารด้วย r แล้วได้หน่วย ทิศเพิ่ม θ ต้องมีองค์ประกอบลงด้าน z ลบ'),
 ('สร้างฐานมุมรอบแกน', F('∂<b>r</b>','∂ϕ')+'=r sinθ'+U('ϕ')+' ⇒ '+U('ϕ')+'='+F('1','r sinθ')+F('∂<b>r</b>','∂ϕ'), 'ฐาน ϕ ตรงกับทรงกระบอก แต่ตัวประกอบสเกลเป็นรัศมีวงรอบแกน r sinθ'),
 ('แปลงสนาม ไม่ใช่เพียงจุด', '<em>A</em><sub>ρ</sub>=<em>A</em><sub>r</sub>sinθ+<em>A</em><sub>θ</sub>cosθ<br><em>A</em><sub>z</sub>=<em>A</em><sub>r</sub>cosθ−<em>A</em><sub>θ</sub>sinθ; <em>A</em><sub>ϕ,cyl</sub>=<em>A</em><sub>ϕ,sph</sub>', 'แทนฐานใหม่ใน A แล้วรวบรวมสัมประสิทธิ์ฐานเดียวกัน จะได้การแปลงเวกเตอร์โดยตรง'),
 ('หาความยาวส่วนย่อยทั้งสาม', 'd<b>l</b>=dr'+U('r')+'+r dθ'+U('θ')+'+r sinθ dϕ'+U('ϕ'), 'แนวรัศมีเป็นระยะตรง แนว θ เป็นส่วนโค้งรัศมี r และแนว ϕ เป็นส่วนโค้งรัศมี r sinθ'),
 ('คูณด้านบนผิวทรงกลม', 'd<b>s</b><sub>r</sub>=(r dθ)(r sinθ dϕ)'+U('r')+'=r²sinθ dθdϕ'+U('r')+'<br>dv=r²sinθ drdθdϕ', 'ผิว r คงที่มีด้านมุมสองแนว ตั้งปกติออกจากศูนย์กลาง แล้วเพิ่มความหนา dr เพื่อเป็นปริมาตร'),
 ('ตรวจพื้นที่ทรงกลมด้วยมือ', 'S=r²∫<sub>0</sub><sup>2π</sup>dϕ ∫<sub>0</sub><sup>π</sup>sinθ dθ=r²[ϕ]<sub>0</sub><sup>2π</sup>[−cosθ]<sub>0</sub><sup>π</sup>=4πr²', 'หากตก sinθ ผลจะไม่ใช่พื้นที่ทรงกลม เป็นการตรวจส่วนย่อยที่เป็นอิสระจากสูตรแปลงฐาน')],
 ['θ=0 หรือ π ทำให้ ϕ ไม่กำหนด ฐานมุมไม่เป็นเอกลักษณ์', 'โหมดองศาใช้แทนค่ามุมโจทย์ได้ แต่อนุพันธ์และปริพันธ์มุมต้องใช้เรเดียน', 'การแปลงฐานต้องรักษา |A|² ใช้เป็นตัวตรวจคำตอบ MID-Q01'],
 ['ลูกทรงกลมประจุและตัวนำทรงกลมใช้ผิวเกาส์ที่สนามมีขนาดคงที่ จึงเปลี่ยนปัญหาสามมิติเป็นสมการรัศมีได้', 'ความเข้าใจมุมและพื้นที่จำเป็นต่อการนับฟลักซ์หรือกำลังแผ่รังสีของเสาอากาศในวิชาถัดไป การอินทิเกรตทั่วทรงกลมต้องมี sinθ เสมอ'],
 'เมื่อ θ=90° ฐาน r และ θ ชี้แนวใด? ใช้ภาพตรวจเครื่องหมายขององค์ประกอบ z', 'r>0, 0≤θ≤π, และมุม ϕ วัดบนระนาบ xy จาก +x')

lesson(4, [
 'กฎคูลอมบ์เป็นกฎเชิงประจักษ์ของแรงระหว่างประจุจุด ไม่ใช่สูตรที่อนุมานจากการรวมเวกเตอร์เพียงอย่างเดียว หลังรับกฎนี้แล้ว เราใช้เรขาคณิตเพื่อคำนวณขนาดและทิศ แรงจากแหล่งหลายตัวรวมกันเป็นลูกศรที่ประจุเป้าหมายเดียว',
 'ประจุชนิดเดียวกันผลักออกจากแหล่ง ประจุต่างชนิดดึงกลับหาแหล่ง เลือกเวกเตอร์จากแหล่งไปผู้รับก่อน แล้วให้เครื่องหมายผลคูณประจุจัดการกลับทิศ การกลับทั้งเวกเตอร์และเครื่องหมายซ้ำจะทำให้แรงผิด'], [
 ('กฎทั่วไปก่อนข้อมูลตำแหน่ง', '<b>F</b><sub>2←1</sub>='+F('<em>q</em><sub>1</sub><em>q</em><sub>2</sub>','4πεR²')+U('R'), 'ใช้ประจุจุดในตัวกลางเนื้อเดียว เลขห้อยบอกชัดว่าหาแรงบนผู้รับ 2 จากแหล่ง 1'),
 ('สร้างระยะจากแหล่งไปผู้รับ', '<b>R</b>=<b>r</b><sub>2</sub>−<b>r</b><sub>1</sub>; R=√[(x<sub>2</sub>−x<sub>1</sub>)²+(y<sub>2</sub>−y<sub>1</sub>)²+(z<sub>2</sub>−z<sub>1</sub>)²]', 'การลบตำแหน่งกำหนดทิศระยะ ใช้ระยะบวก R ในตัวส่วนเสมอ'),
 ('แทนเวกเตอร์หน่วยอย่างครบถ้วน', U('R')+'='+F('<b>R</b>','R')+' ⇒ <b>F</b><sub>2←1</sub>='+F('<em>q</em><sub>1</sub><em>q</em><sub>2</sub>','4πεR³')+'<b>R</b>', 'R ที่เป็นเวกเตอร์มีขนาด R จึงต้องหารกำลังสามเพื่อให้ขนาดแรงยังแปรผกผันระยะกำลังสอง'),
 ('ใช้การซ้อนทับ', '<b>F</b><sub>2</sub>=Σ<sub>i≠2</sub>'+F('<em>q</em><sub>i</sub><em>q</em><sub>2</sub>','4πε|<b>R</b><sub>i2</sub>|³')+'<b>R</b><sub>i2</sub>', 'ไม่รวมแรงที่ประจุกระทำกับตนเอง ต้องสร้างระยะใหม่สำหรับแต่ละแหล่ง'),
 ('ตัวอย่างเพื่อเห็นเครื่องหมาย', '<em>q</em><sub>1</sub>=1 nC ที่ (0,0,0), <em>q</em><sub>2</sub>=−2 nC ที่ (0.1,0,0) m<br><b>R</b>=0.1'+U('x')+' m; <b>F</b><sub>2←1</sub>≈−1.798×10<sup>−6</sup>'+U('x')+' N', 'แปลง nC เป็น 10⁻⁹ C ทั้งสองประจุ แล้วใช้ ε₀ ผลติดลบชี้กลับหาแหล่งตามแรงดึง'),
 ('ตั้งสมดุลทุกองค์ประกอบ', '<b>F</b><sub>เพิ่ม</sub>=−<b>F</b><sub>เดิม</sub> ⇒ F<sub>x,รวม</sub>=F<sub>y,รวม</sub>=F<sub>z,รวม</sub>=0', 'การหักล้างต้องตรงทั้งทิศและขนาด หากไม่กำหนดประจุเพิ่ม ระยะที่เลือกเปลี่ยนได้เมื่อปรับประจุตามระยะกำลังสอง'),
 ('ตรวจขนาดด้วยการเพิ่มระยะ', 'R → 2R ⇒ |<b>F</b>| → '+F('|<b>F</b>|','4'), 'ตรวจสัดส่วนได้โดยไม่ต้องคำนวณใหม่ ช่วยจับการใช้ R³ กับเวกเตอร์หน่วยผิดรูป')],
 ['ต้นฉบับ MID-Q02 ใช้ C ห้ามเปลี่ยนเป็น µC เพราะคุ้นกับโจทย์ตำรา', 'ระบุแรงบนประจุตัวใดก่อนลบตำแหน่ง', 'คำตอบตำแหน่ง Q₄ มีหลายกรณีเมื่อขนาด Q₄ ยังเลือกได้ ต้องระบุค่ากับตำแหน่งคู่กัน'],
 ['การซ้อนทับเป็นฐานของสนามประจุต่อเนื่อง เพราะเมื่อแบ่งแหล่งเล็กลง ผลรวมแรงจะกลายเป็นปริพันธ์', 'แรงไฟฟ้าในเครื่องแยกฝุ่นไฟฟ้าสถิตขึ้นกับสนามและประจุอนุภาค ความเข้าใจทิศแรงสำคัญเมื่อประจุอนุภาคเป็นลบ'],
 'ถ้ากลับเครื่องหมายทั้งสองประจุพร้อมกัน แรงระหว่างคู่เดิมเปลี่ยนหรือไม่?', 'ประจุอยู่นิ่ง แหล่งเป็นจุดและระยะไม่เป็นศูนย์ ใช้ตัวกลางเนื้อเดียวเชิงเส้น')

lesson(5, [
 'สนามคือแรงต่อประจุทดสอบบวกหนึ่งหน่วย จึงเป็นแผนที่ของแหล่งก่อนนำประจุเป้าหมายมาวาง สำหรับลวดประจุ แต่ละส่วนเล็กสร้างลูกศรต่างทิศ การบวกสนามต้องทำทีละองค์ประกอบก่อนอินทิเกรต',
 'ลวดช่วง 0 ถึง L ไม่สมมาตรสองด้านของจุดบนระนาบ z=0 ลูกศรตาม z จึงไม่หักล้าง การจำว่าลวดสร้างสนามรัศมีอย่างเดียวใช้ได้เฉพาะลวดอนันต์ หรือจุดกึ่งกลางของลวดสมมาตรเท่านั้น'], [
 ('สูตรทั่วไปของสนามประจุต่อเนื่อง', '<b>E</b>(<b>r</b>)='+F('1','4πε')+'∫'+F('<b>R</b> dq','R³')+'; <b>R</b>=<b>r</b>−<b>r</b>′', 'เครื่องหมายไพรม์แยกจุดแหล่งที่เคลื่อนระหว่างอินทิเกรตออกจากจุดสังเกตที่ตรึง'),
 ('แบ่งลวดและตั้งเรขาคณิต', 'dq=ρ<sub>l</sub>dz′; <b>R</b>=ρ'+U('ρ')+'−z′'+U('z')+'; R²=ρ²+z′²', 'ลวดอยู่บนแกน z จุดสังเกตอยู่ z=0 ความหนาแน่นเชิงเส้นคงที่จึงดึงออกจากปริพันธ์ได้'),
 ('แยกองค์ประกอบก่อนหาปริพันธ์', '<em>E</em><sub>ρ</sub>='+F('ρ<sub>l</sub>','4πε')+'∫<sub>0</sub><sup>L</sup>'+F('ρ dz′','(ρ²+z′²)<sup>3/2</sup>')+'<br><em>E</em><sub>z</sub>='+F('ρ<sub>l</sub>','4πε')+'∫<sub>0</sub><sup>L</sup>'+F('−z′ dz′','(ρ²+z′²)<sup>3/2</sup>'), 'ฐานรัศมีที่จุดสังเกตไม่เปลี่ยนตาม z′ แต่แต่ละองค์ประกอบมีตัวเศษต่างกัน จึงต้องอินทิเกรตแยก'),
 ('แทนตรีโกณมิติในส่วนรัศมี', 'z′=ρ tanψ; dz′=ρ sec²ψ dψ; ρ²+z′²=ρ²sec²ψ<br>ψ: 0 → arctan'+F('L','ρ'), 'ใช้ 1+tan²ψ=sec²ψ และ ρ>0 ช่วงมุมอยู่ระหว่าง 0 กับ π/2 จึง secψ เป็นบวก'),
 ('ลดรูปและประเมินขอบเขต', '∫'+F('ρ dz′','(ρ²+z′²)<sup>3/2</sup>')+'='+F('1','ρ')+'∫cosψ dψ<br>'+F('1','ρ')+'[sinψ]<sub>0</sub><sup>arctan(L/ρ)</sup>='+F('L','ρ√(ρ²+L²)'), 'ตัวเศษมี ρ²sec²ψ ตัวส่วนมี ρ³sec³ψ เหลือ cosψ/ρ แล้วใช้สามเหลี่ยมด้าน ρ,L'),
 ('ส่วนตามแกนด้วยการแทนตัวแปร', 'u=ρ²+z′²; du=2z′dz′<br>−'+F('1','2')+'∫<sub>ρ²</sub><sup>ρ²+L²</sup>u<sup>−3/2</sup>du=[u<sup>−1/2</sup>]<sub>ρ²</sub><sup>ρ²+L²</sup>='+F('1','√(ρ²+L²)')+'−'+F('1','ρ'), 'กำลัง −3/2 อินทิเกรตเป็น −2u⁻¹/² ลบสองตัวจึงตัดกัน แต่ค่าปลายลบต้นยังติดลบ'),
 ('ประกอบสนามทั่วไปของช่วง 0 ถึง L', '<b>E</b>='+F('ρ<sub>l</sub>','4πε')+'['+F('L','ρ√(ρ²+L²)')+U('ρ')+'+('+F('1','√(ρ²+L²)')+'−'+F('1','ρ')+')'+U('z')+']', 'ประจุบวกให้รัศมีบวกและ z ลบตามภาพ ตรวจหน่วยวงเล็บเป็น m⁻¹ แล้ว ρl/ε เป็น V'),
 ('แทนข้อมูล MID-Q03', 'ρ=3 m, L=4 m ⇒ √(ρ²+L²)=5 m<br><b>E</b>='+F('ρ<sub>l</sub>','4πε<sub>0</sub>')+'('+F('4','15')+U('y')+'−'+F('2','15')+U('z')+') m<sup>−1</sup>', 'ที่ P(0,3,0) ฐานรัศมีคือ y บวก รักษา π และ ε₀ ตามคำสั่งต้นฉบับ คำตอบรวมมีหน่วย V/m')],
 ['ห้ามดึงเวกเตอร์ระยะออกจากปริพันธ์ เพราะมันเปลี่ยนตามแหล่ง', 'เปลี่ยนตัวแปรต้องเปลี่ยนขอบเขตพร้อมกัน', 'ลวดด้านเดียวมี Ez ไม่เป็นศูนย์ แม้จุดสังเกตอยู่ z=0'],
 ['สนามใกล้ปลายบัสบาร์หรืออิเล็กโทรดไม่เหมือนแบบจำลองอนันต์ การรู้ว่าสมมาตรถูกทำลายตรงไหนช่วยประเมินข้อจำกัดของสูตร', 'วิธีแบ่งแหล่งและรวมสนามจะกลับมาในบิโอต์–ซาวารต์ ต่างกันที่แหล่งเป็นกระแสและใช้ผลคูณไขว้แทนเวกเตอร์รัศมี'],
 'ถ้าต่อเพิ่มลวดจาก −L ถึง 0 ส่วน Ez จะเปลี่ยนอย่างไร? อธิบายด้วยคู่แหล่งที่ z′ และ −z′', 'ประจุลวดคงที่ ตัวกลางเนื้อเดียว จุดสังเกตห่างแกน ρ>0')

lesson(6, [
 'ฟลักซ์วัดการทะลุผิว สนามที่วิ่งเฉียดผิวแรงเพียงใดก็ไม่ทะลุ เพราะต้องฉายบนปกติของผิว ผิวจึงมีทั้งขนาดพื้นที่และทิศ หากกลับปกติ เครื่องหมายฟลักซ์กลับทันที แต่สนามจริงไม่เปลี่ยน',
 'D แยกบทบาทแหล่งประจุอิสระออกจากการตอบสนองของวัสดุ ขณะที่ E วัดแรงต่อประจุทดสอบ ในอวกาศว่าง D=ε₀E และในตัวกลางเชิงเส้นไอโซทรอปิก D=εE จึงอย่าตีความ D ว่าเป็นแรง'], [
 ('นิยามฟลักซ์ทั่วไป', 'Ψ=∫<sub>S</sub><b>D</b> • d<b>s</b>; d<b>s</b>=ds'+U('n'), 'ผิวเปิดต้องเลือกปกติก่อน ผิวปิดใช้ปกติชี้ออกตลอดผิว'),
 ('แยกส่วนที่ทะลุ', '<b>D</b> • d<b>s</b>=|<b>D</b>|cosα ds', 'α วัดระหว่าง D กับปกติ ไม่ใช่ระหว่าง D กับระนาบผิว'),
 ('ผิวแบนในสนามสม่ำเสมอ', 'Ψ=D cosα∫<sub>S</sub>ds=DS cosα', 'ดึง D และมุมออกได้เฉพาะเมื่อทั้งสองคงที่บนผิว หากสนามไม่สม่ำเสมอต้องคงไว้ในปริพันธ์'),
 ('สนามรัศมีบนทรงกลม', '<b>D</b>='+F('Q','4πr²')+U('r')+'; d<b>s</b>=r²sinθ dθdϕ'+U('r'), 'สนามของประจุจุดตั้งฉากทรงกลมทุกตำแหน่ง ผลคูณจุดฐานรัศมีเดียวกันเท่ากับหนึ่ง'),
 ('อินทิเกรตทั้งทรงกลม', 'Ψ='+F('Q','4π')+'∫<sub>0</sub><sup>2π</sup>dϕ ∫<sub>0</sub><sup>π</sup>sinθ dθ='+F('Q','4π')+'(2π)(2)=Q', 'r² ของสนามตัดกับ r² ของพื้นที่ สนามไกลออกอ่อนลงแต่ผิวโตชดเชยกันพอดี'),
 ('ผิวหนึ่งส่วนแปดอย่างครบขั้น', 'Ψ<sub>octant</sub>='+F('Q','4π')+'[ϕ]<sub>0</sub><sup>π/2</sup>[−cosθ]<sub>0</sub><sup>π/2</sup>='+F('Q','8'), 'นี่คือวิธีทำด้วยมือของ Hayt D3.1(a) ไม่ข้ามไปบอกหนึ่งส่วนแปดโดยไม่แสดงขอบเขต'),
 ('ตรวจมิติ', '[Ψ]=[D][S] = (C/m²)(m²)=C', 'ฟลักซ์ไฟฟ้าในนิยาม D มีหน่วย C ส่วนฟลักซ์แม่เหล็กที่จะเรียนต่อมีหน่วย Wb')],
 ['อย่าสลับ D กับ E ในการนับประจุ', 'มุมของผิวต้องวัดกับปกติ', 'ผลเป็นศูนย์บนผิวหนึ่งไม่ได้พิสูจน์ว่าสนามทุกจุดเป็นศูนย์'],
 ['หน้าขดลวดต้องวางให้ปกติรับสนามได้มากที่สุดเพื่อรับฟลักซ์ แนวคิดการฉายเดียวกันจะใช้คำนวณฟลักซ์แม่เหล็กและแรงดันเหนี่ยวนำ', 'การตรวจฉนวนแรงสูงต้องแยกสนาม E ที่เกี่ยวข้องกับความเค้นฉนวนออกจาก D ที่ใช้เงื่อนไขประจุและรอยต่อ'],
 'สนามขนานผิวมีฟลักซ์เท่าใด และเมื่อกลับปกติของผิว สนามเปลี่ยนหรือฟลักซ์เปลี่ยน?', 'ตัวอย่างใช้สนามประจุจุดสถิตและผิวทรงกลมศูนย์กลางเดียวกัน')

lesson(7, [
 'กฎเกาส์บอกว่าประจุอิสระที่อยู่ข้างในเป็นยอดสุทธิของฟลักซ์ออกจากผิวปิด สนามจากประจุภายนอกอาจเข้าและออกผิว แต่ไม่เพิ่มยอดสุทธิ กฎนี้เป็นกฎสนามพื้นฐาน การใช้กฎเพื่อหา E ได้ง่ายต้องมีสมมาตรช่วยแยกขนาดสนามออกจากปริพันธ์',
 'สำหรับลวดอนันต์ ไม่มีปลายให้สนามเอียงตาม z และไม่มีมุมพิเศษรอบแกน สนามจึงชี้รัศมีและมีขนาดเท่ากันบนผิวทรงกระบอก ผิวที่เลือกเป็นเครื่องมือคำนวณ ไม่จำเป็นต้องเป็นผิววัสดุจริง'], [
 ('กฎทั่วไปก่อนเลือกผิว', '∯<sub>S</sub><b>D</b> • d<b>s</b>=Q<sub>enc</sub>=∫<sub>v</sub>ρ<sub>v</sub>dv', 'ใช้ผิวปิดกับปกติออก และนับเฉพาะประจุที่ล้อม ไม่ใช่ประจุทั้งหมดในจักรวาล'),
 ('กำหนดผิวสำหรับลวดอนันต์', 'ρ=a, 0≤z≤L; <b>D</b>=D<sub>ρ</sub>(a)'+U('ρ'), 'สมมาตรการเลื่อนและการหมุนทำให้ D ไม่ขึ้นกับ z หรือ ϕ บนผิวข้าง'),
 ('แยกฝาจากผิวข้าง', '<b>D</b> • d<b>s</b><sub>ฝา</sub>=D<sub>ρ</sub>'+U('ρ')+' • (±'+U('z')+'ds)=0', 'บนฝาสนามขนานระนาบ จึงไม่ทะลุ ไม่ได้แปลว่าสนามบนฝาเป็นศูนย์'),
 ('อินทิเกรตผิวข้างด้วยมือ', '∯<sub>S</sub><b>D</b> • d<b>s</b>=D<sub>ρ</sub>(a)∫<sub>0</sub><sup>L</sup>dz ∫<sub>0</sub><sup>2π</sup>a dϕ=2πaL D<sub>ρ</sub>(a)', 'a เป็นรัศมีคงที่ของผิว ส่วน L เป็นความยาวผิวที่เลือก ไม่ใช่ความยาวลวดอนันต์'),
 ('นับประจุที่ล้อม', 'Q<sub>enc</sub>=∫<sub>0</sub><sup>L</sup>ρ<sub>l</sub>dz=ρ<sub>l</sub>L', 'ความหนาแน่นเชิงเส้นมีหน่วย C/m คูณความยาวจึงได้ C'),
 ('แก้สนามจากสองด้าน', '2πaL D<sub>ρ</sub>=ρ<sub>l</sub>L ⇒ <b>D</b>='+F('ρ<sub>l</sub>','2πρ')+U('ρ')+'; <b>E</b>='+F('ρ<sub>l</sub>','2περ')+U('ρ'), 'L ตัดกันเพราะสนามไม่ขึ้นกับความยาวผิวที่เลือก เปลี่ยน a ซึ่งเป็นรัศมีผิวกลับเป็นตัวแปรจุดสังเกต ρ'),
 ('ตรวจกรณีที่ไม่มีสมมาตร', '∯<sub>S</sub><b>D</b> • d<b>s</b>=Q<sub>enc</sub> ยังจริง แต่ D ไม่คงที่ ⇒ ดึง D ออกไม่ได้', 'สำหรับลวดจำกัด กฎเกาส์ยังจริงทุกผิว แต่ข้อมูลฟลักซ์รวมเพียงค่าเดียวไม่พอระบุสนามทุกจุด')],
 ['ผิวเปิดใช้กฎเกาส์รูป Qenc โดยตรงไม่ได้', 'ศูนย์ฟลักซ์สุทธิไม่แปลว่าสนามศูนย์', 'อย่าใช้สมมาตรลวดอนันต์กับ MID-Q03 ซึ่งเป็นลวดจำกัด'],
 ['สายโคแอกเชียลมีสนามรัศมีในฉนวน การหาสนามด้วยเกาส์แล้วอินทิเกรตศักย์จะนำไปสู่ความจุต่อความยาว', 'การเลือกรูปร่างผิวตามแหล่งเป็นนิสัยเดียวกับการเลือกวงแอมแปร์ตามสมมาตรสนามแม่เหล็กในบัสบาร์และแกนวงแหวน'],
 'ผิวที่ไม่มีประจุข้างในแต่มีประจุอยู่ภายนอก อาจมีสนามบนผิวหรือไม่? แยกคำว่าแต่ละจุดกับยอดสุทธิ', 'ลวดอนันต์ ประจุเชิงเส้นสม่ำเสมอ ตัวกลางเนื้อเดียว')

lesson(8, [
 'ไดเวอร์เจนซ์ถามว่ากล่องเล็กมีสนามไหลออกมากกว่าไหลเข้าเท่าใดต่อปริมาตร คำว่าแหล่งจึงหมายถึงความไม่สมดุลของฟลักซ์ในบริเวณเล็ก ไม่ใช่ดูเพียงลูกศรที่ยาวหรือโค้ง',
 'เมื่อเอากล่องเล็กหลายกล่องมาต่อกัน ฟลักซ์ผ่านผิวภายในถูกนับออกจากกล่องหนึ่งและเข้าอีกกล่องหนึ่ง จึงตัดกัน เหลือแต่ผิวด้านนอก นี่คือภาพกายภาพของทฤษฎีบทไดเวอร์เจนซ์'], [
 ('นิยามทั่วไปของตัวดำเนินการ', '∇ • <b>D</b>=lim<sub>Δv→0</sub>'+F('∯<sub>∂Δv</sub><b>D</b> • d<b>s</b>','Δv'), 'นิยามเป็นยอดออกต่อปริมาตร ใช้ปกติออกจากกล่องทุกหน้า'),
 ('เทียบหน้าซ้ายและขวา', 'ΔΨ<sub>x</sub>=[D<sub>x</sub>(x+Δx/2)−D<sub>x</sub>(x−Δx/2)]ΔyΔz', 'หน้าขวามีปกติ +x หน้าซ้าย −x จึงเป็นผลต่างขององค์ประกอบ ไม่ใช่ผลบวก'),
 ('ขยายเทย์เลอร์และตัดค่าคงที่', 'D<sub>x</sub>(x±Δx/2)≈D<sub>x</sub>(x)±'+F('Δx','2')+F('∂D<sub>x</sub>','∂x')+'<br>ΔΨ<sub>x</sub>≈'+F('∂D<sub>x</sub>','∂x')+'ΔxΔyΔz', 'พจน์ D ที่จุดกลางหักล้าง เหลืออัตราเปลี่ยนตามแนวปกติคูณปริมาตร'),
 ('รวมสามแกนและหารปริมาตร', '∇ • <b>D</b>='+F('∂D<sub>x</sub>','∂x')+'+'+F('∂D<sub>y</sub>','∂y')+'+'+F('∂D<sub>z</sub>','∂z'), 'เมื่อหาร ΔxΔyΔz แล้วให้กล่องเล็กลง พจน์อันดับสูงหายไป เหลืออนุพันธ์ทั้งสามแกน'),
 ('เชื่อมกับประจุที่จุด', '∯<sub>S</sub><b>D</b> • d<b>s</b>=∫<sub>v</sub>ρ<sub>v</sub>dv ⇒ ∇ • <b>D</b>=ρ<sub>v</sub>', 'ใช้เกาส์กับกล่องเล็กทุกตำแหน่ง ปริมาณต่อปริมาตรด้านขวาคือความหนาแน่นประจุ'),
 ('รวมกล่องเป็นทฤษฎีบท', '∫<sub>v</sub>(∇ • <b>D</b>)dv=∯<sub>∂v</sub><b>D</b> • d<b>s</b>', 'ผิวภายในมีปกติสวนกันจึงตัดกัน เหลือฟลักซ์ผ่านผิวปิดด้านนอก'),
 ('ตัวอย่างที่แยกสนามจากแหล่ง', '<b>D</b>=kx'+U('x')+'+ky'+U('y')+'+kz'+U('z')+' ⇒ ∇ • <b>D</b>=k+k+k=3k', 'k มีหน่วย C/m³ แต่สนามมีหน่วย C/m² หาก D เป็นค่าคงที่ทั้งบริเวณ divergence จะเป็นศูนย์แม้สนามไม่ศูนย์')],
 ['ไดเวอร์เจนซ์ให้สเกลาร์ ส่วน curl ให้เวกเตอร์', 'พิกัดโค้งมีตัวประกอบสเกล ห้ามใช้สูตรฉากแทน', 'จุดเอกฐานของประจุจุดต้องแยกออกจากบริเวณที่สนามเรียบ'],
 ['การอนุรักษ์ประจุในตัวนำจะเขียนเป็น divergence ของ J เท่ากับอัตราประจุลด การเข้าใจกล่องเล็กทำให้เครื่องหมายลบของสมการต่อเนื่องเป็นเหตุผลแทนการท่อง', 'การตรวจผลจำลองสนามใช้ยอดฟลักซ์กับประจุในเซลล์เป็นตัวตรวจสมดุลเชิงกายภาพ ก่อนเชื่อภาพลูกศรที่ดูสวย'],
 'สนาม D คงที่มี divergence เท่าใด และเหตุใดฟลักซ์ออกจากด้านหนึ่งจึงไม่ทำให้มีแหล่งสุทธิ?', 'สนามเรียบในบริเวณที่ใช้อนุพันธ์ ผิวปิดวางปกติออก')

lesson(9, [
 'ศักย์คือบัญชีพลังงานต่อประจุ ไม่ใช่ลูกศรแรง สนามไฟฟ้าสถิตชี้จากศักย์สูงไปต่ำ แต่แรงบนประจุลบชี้สวนสนาม การบอกว่างานบวกหรือลบจึงต้องระบุว่าใครทำงาน ประจุอะไร และย้ายจากจุดไหนไปจุดไหน',
 'การย้ายประจุบวกเข้าใกล้แหล่งบวกช้า ๆ ต้องออกแรงสวนแรงผลัก ภายนอกจึงทำงานบวกและพลังงานศักย์เพิ่ม ส่วนแรงสนามทำงานลบ เหมือนยกวัตถุขึ้นในสนามโน้มถ่วง แต่ประจุลบทำให้เครื่องหมายพลังงานกลับได้'], [
 ('สูตรทั่วไปจากงานต่อประจุ', 'V<sub>A</sub>−V<sub>B</sub>=−∫<sub>B</sub><sup>A</sup><b>E</b> • d<b>l</b>', 'กำหนดจุดเริ่ม B และปลาย A ให้ชัด ลบมาจากงานของสนามเป็นลบของการเพิ่มพลังงานศักย์'),
 ('เชื่อมกับงานสองชนิด', 'ΔW<sub>potential</sub>=q(V<sub>A</sub>−V<sub>B</sub>)<br>W<sub>ext</sub>=qΔV; W<sub>field</sub>=−qΔV', 'งานภายนอกรูปนี้ใช้การย้ายช้ามากโดยพลังงานจลน์ไม่เปลี่ยน จึงชดเชยแรงสนามพอดี'),
 ('ลดเป็นความสัมพันธ์ ณ จุด', 'dV=−<b>E</b> • d<b>l</b>=−E<sub>x</sub>dx−E<sub>y</sub>dy−E<sub>z</sub>dz', 'เปรียบเทียบกับดิฟเฟอเรนเชียลรวมของฟังก์ชัน V เพื่ออ่านองค์ประกอบสนาม'),
 ('อ่านเกรเดียนต์ครบสามแกน', '<b>E</b>=−∇V=−('+F('∂V','∂x')+U('x')+'+'+F('∂V','∂y')+U('y')+'+'+F('∂V','∂z')+U('z')+')', 'เกรเดียนต์ชี้ทางเพิ่มศักย์เร็วที่สุด สนามจึงชี้สวนทางในไฟฟ้าสถิต'),
 ('ปริพันธ์สนามประจุจุด', 'V(r)−V(∞)=−'+F('Q','4πε')+'∫<sub>∞</sub><sup>r</sup>r′<sup>−2</sup>dr′='+F('Q','4πε')+'['+F('1','r′')+']<sub>∞</sub><sup>r</sup>='+F('Q','4πεr'), 'ใช้ ∫r′⁻²dr′=−1/r′ แล้วลบจากนิยามศักย์ตัดกับลบจากปริพันธ์ กำหนดศูนย์ที่อนันต์'),
 ('รูปปริพันธ์ของ MID-Q04', '∫'+F('r dr','(r²+a²)²')+'='+F('1','2')+'∫u<sup>−2</sup>du=−'+F('1','2u')+'; u=r²+a²', 'du=2rdr เปลี่ยนตัวแปรให้ปริพันธ์เป็นกำลังธรรมดา แสดงเครื่องหมายก่อนประเมินขอบเขต'),
 ('ความต่างศักย์และค่าที่อนันต์', 'V<sub>AB</sub>='+F('1','2ε<sub>0</sub>')+'['+F('1','r<sub>A</sub>²+a²')+'−'+F('1','r<sub>B</sub>²+a²')+']<br>V(r)='+F('1','2ε<sub>0</sub>(r²+a²)')+' เมื่อ V(∞)=0', 'รักษาสัมประสิทธิ์สนามตามโจทย์ หาก rA<rB จะได้ VAB บวก สำหรับประจุบวกงานภายนอกจึงเป็นบวก'),
 ('ตรวจโดยย้อนอนุพันธ์', '−'+F('dV','dr')+'='+F('r','ε<sub>0</sub>(r²+a²)²')+'=E<sub>r</sub>', 'คืนสนามเดิมเป็นการตรวจทั้งเครื่องหมายและตัวประกอบสองโดยไม่ใช้วิธีเดิมซ้ำ')],
 ['VAB คือ VA−VB ห้ามกลับขอบโดยลืมลบ', 'งานภายนอกและงานของสนามมีเครื่องหมายตรงข้าม', 'ศักย์สัมบูรณ์ยังต้องเลือกศูนย์อ้างอิง เช่น V(∞)=0'],
 ['ความต่างศักย์กำหนดพลังงานที่แหล่งจ่ายให้ประจุในวงจร แต่สนามในฉนวนเป็นความชันเชิงพื้นที่ของศักย์ จึงอาจสูงมากในช่องว่างเล็กแม้แรงดันไม่สูงมาก', 'ในเครื่องจักรไฟฟ้า การแยกงานไฟฟ้า พลังงานสะสม และงานกลช่วยตรวจการอนุรักษ์พลังงานได้ ปริมาณ qV เป็นจุดเริ่มต้นก่อนเรียนพลังงานสนามและแรงบิด'],
 'ถ้า VAB บวก ประจุลบย้ายจาก B ไป A จะมีพลังงานศักย์เพิ่มหรือลด? ระบุงานของทั้งสนามและภายนอก', 'ไฟฟ้าสถิต สนามอนุรักษ์ งานภายนอกย้ายแบบพลังงานจลน์คงที่')

lesson(10, [
 'ในโลหะ อิเล็กตรอนเคลื่อนเร็วจากพลังงานความร้อน แต่ทิศสุ่มทำให้ค่าเฉลี่ยเป็นศูนย์ เมื่อมีสนามไฟฟ้า อิเล็กตรอนถูกเร่งระหว่างการกระเจิงกับโครงผลึกและสิ่งรบกวน แล้วได้ความเร็วเฉลี่ยเล็กที่เรียกว่า drift ความเร็วนี้สวน E เพราะประจุอิเล็กตรอนเป็นลบ',
 'กระแสตามข้อตกลงชี้ทิศการขนประจุบวก ดังนั้นอิเล็กตรอนเคลื่อนสวนสนามแต่ J กลับชี้ตามสนาม การชนไม่ได้ทำให้อิเล็กตรอนหยุดตลอดเวลา แบบจำลองเวลาผ่อนคลายแทนผลเฉลี่ยของการกระเจิงจำนวนมาก',
 'หากประจุออกจากกล่องมากกว่าที่เข้า ประจุสะสมในกล่องต้องลด สมการต่อเนื่องเป็นบัญชีประจุและจริงแม้กระแสเปลี่ยนเวลา ต่างจากกฎโอห์มเฉพาะที่ซึ่งเป็นแบบจำลองวัสดุ'], [
 ('สูตรทั่วไปของกระแสผ่านผิว', 'I=∫<sub>S</sub><b>J</b> • d<b>s</b>; J<sub>n</sub>='+F('dQ','dt ds'), 'เลือกผิวและปกติก่อน เครื่องหมายกระแสขึ้นกับทิศที่เลือก หน่วย J เป็น A/m²'),
 ('นับประจุที่เคลื่อนผ่านพื้นที่', 'ΔQ=ρ<sub>v</sub>(v<sub>n</sub>Δt)Δs ⇒ J<sub>n</sub>=ρ<sub>v</sub>v<sub>n</sub> ⇒ <b>J</b>=ρ<sub>v</sub><b>v</b>', 'ในเวลา Δt ประจุในแท่งยาว vnΔt ผ่านพื้นที่ Δs จึงได้กระแสพาจากปริมาตรที่เคลื่อน'),
 ('แบบจำลอง drift ของอิเล็กตรอน', 'm'+F('d<b>v</b><sub>d</sub>','dt')+'=−e<b>E</b>−'+F('m<b>v</b><sub>d</sub>','τ')+'; ภาวะคงตัว: <b>v</b><sub>d</sub>=−'+F('eτ','m')+'<b>E</b>', 'e คือขนาดประจุอิเล็กตรอนเป็นบวก ส่วน τ เป็นเวลาผ่อนคลาย ในภาวะเฉลี่ยคงตัวอนุพันธ์เวลาเป็นศูนย์'),
 ('คืนกฎโอห์มเฉพาะที่', '<b>J</b>=(−ne)<b>v</b><sub>d</sub>='+F('ne²τ','m')+'<b>E</b>=σ<b>E</b>', 'n เป็นจำนวนอิเล็กตรอนต่อปริมาตร ลบของประจุกับลบของ drift ตัดกัน ความนำต้องเป็นบวกในแบบจำลองนี้'),
 ('อนุรักษ์ประจุในปริมาตรอยู่นิ่ง', '∯<sub>S</sub><b>J</b> • d<b>s</b>=−'+F('d','dt')+'∫<sub>v</sub>ρ<sub>v</sub>dv', 'ซ้ายเป็นกระแสสุทธิออก หากเป็นบวก ประจุภายในลดจึงมีลบหน้าการเปลี่ยนประจุ'),
 ('แปลงเป็นรูปจุด', '∫<sub>v</sub>[∇ • <b>J</b>+'+F('∂ρ<sub>v</sub>','∂t')+']dv=0 ⇒ ∇ • <b>J</b>=−'+F('∂ρ<sub>v</sub>','∂t'), 'ใช้ divergence theorem และปริมาตรคงที่ เนื่องจากจริงสำหรับทุกกล่อง อินทิแกรนด์จึงต้องเป็นศูนย์'),
 ('ทำ ALL-Q01 โดยไม่ข้ามอนุพันธ์', 'J<sub>r</sub>='+F('e<sup>−t</sup>','r')+' ⇒ ∇ • <b>J</b>='+F('1','r²')+F('∂(r²J<sub>r</sub>)','∂r')+'='+F('1','r²')+F('∂(r e<sup>−t</sup>)','∂r')+'='+F('e<sup>−t</sup>','r²'), 'เป็นรัศมีทรงกลมจึงใช้ r² ไม่ใช่สูตรทรงกระบอก ถือ t คงที่เมื่อหาอนุพันธ์ r'),
 ('อินทิเกรตตามเวลาและกำหนดค่าคงตัว', 'ρ<sub>v</sub>=−'+F('1','r²')+'∫e<sup>−t</sup>dt='+F('e<sup>−t</sup>','r²')+'+c(r,θ,ϕ)<br>ρ<sub>v</sub>→0 เมื่อ t→∞ ⇒ c=0; <b>v</b>='+F('<b>J</b>','ρ<sub>v</sub>')+'=r'+U('r')+' m/s', 'อินทิเกรตเวลาแล้วค่าคงตัวอาจขึ้นกับตำแหน่ง ต้องใช้เงื่อนไขปลายเวลา ต้นฉบับละค่าคงตัวที่ทำให้เลขชี้กำลังไม่มีหน่วยไว้โดยนัย')],
 ['อย่าสับสนความเร็วสุ่มกับความเร็ว drift', '∇•J=0 ใช้เฉพาะเมื่อความหนาแน่นประจุไม่เปลี่ยนเวลา', 'อินทิเกรตตามเวลาต้องเก็บฟังก์ชันตำแหน่งเป็นค่าคงตัวและใช้เงื่อนไขกำหนด'],
 ['บัสบาร์ที่มีกระแสเท่ากันอาจมี J ต่างกันเมื่อพื้นที่ต่าง ความร้อนเฉพาะที่เป็น J•E=σE² จึงต้องพิจารณาหน้าตัดและการกระจายกระแส', 'สมการต่อเนื่องเป็นฐานของกฎกระแสที่โหนด ส่วนการสะสมประจุบนแผ่นตัวเก็บประจุจะทำให้ต้องเพิ่มกระแสการกระจัดใน Set 21'],
 'ถ้า J ชี้ออกและ divergence เป็นบวก ประจุในกล่องเพิ่มหรือลด? ใช้บัญชีประจุก่อนดูสมการ', 'แบบจำลอง Drude เป็นแบบคลาสสิกเฉลี่ย; ความนำคงที่และไม่รวมผลความถี่สูงหรืออุณหภูมิเปลี่ยน')

lesson(11, [
 'ฉนวนมีประจุที่ผูกอยู่กับอะตอมหรือโมเลกุล สนามไฟฟ้าดันประจุบวกและลบให้เลื่อนสัมพัทธ์กันเล็กน้อย เกิดไดโพลจำนวนมากต่อปริมาตรที่เรียก P ประจุไม่ได้ไหลอิสระทะลุวัสดุเหมือนตัวนำ',
 'ประจุผูกมัดเกิดบนผิวหรือในบริเวณที่โพลาไรเซชันเปลี่ยน มันมีผลต่อ E แต่เมื่อใช้ D เราจัดผลนี้ไปอยู่ในคุณสมบัติวัสดุ จึงใช้ประจุอิสระเป็นแหล่งของ divergence D',
 'ใส่ไดอิเล็กทริกแล้วสนามลดหรือไม่ต้องถามสิ่งที่ตรึง ถ้าประจุ Q คงที่ D คงที่และ E ลดเมื่อ ε เพิ่ม แต่ถ้าต่อแหล่งจ่ายแรงดันคงที่ สนาม E≈V/d คงที่และประจุที่แหล่งจ่ายส่งเข้าเพิ่ม'], [
 ('กฎเกาส์ที่รวมประจุทั้งสองชนิด', 'ε<sub>0</sub>∇ • <b>E</b>=ρ<sub>free</sub>+ρ<sub>bound</sub>', 'E ตอบสนองประจุทั้งหมด ต้องแยกชนิดแหล่งก่อนสร้าง D'),
 ('เขียนประจุผูกมัดจากโพลาไรเซชัน', 'ρ<sub>bound</sub>=−∇ • <b>P</b>; ρ<sub>s,bound</sub>=<b>P</b> • '+U('n'), 'ไดโพลข้างในวัสดุหักล้างประจุปลายเมื่อ P สม่ำเสมอ เหลือประจุปลายที่ผิวหรือเมื่อ P ไม่สม่ำเสมอ'),
 ('ย้ายการตอบสนองวัสดุไปด้านซ้าย', '∇ • (ε<sub>0</sub><b>E</b>+<b>P</b>)=ρ<sub>free</sub> ⇒ <b>D</b>≡ε<sub>0</sub><b>E</b>+<b>P</b>', 'นี่เป็นนิยาม D โดยยังไม่ได้สมมติวัสดุเชิงเส้น'),
 ('เพิ่มแบบจำลองวัสดุเชิงเส้น', '<b>P</b>=ε<sub>0</sub>χ<sub>e</sub><b>E</b> ⇒ <b>D</b>=ε<sub>0</sub>(1+χ<sub>e</sub>)<b>E</b>', 'χe ไม่มีหน่วยและเป็นสเกลาร์เฉพาะกรณีไอโซทรอปิก วัสดุทั่วไปอาจตอบสนองไม่ขนาน E'),
 ('นิยามสภาพยอมสัมพัทธ์', 'ε<sub>r</sub>=1+χ<sub>e</sub>; ε=ε<sub>0</sub>ε<sub>r</sub> ⇒ <b>D</b>=ε<b>E</b>', 'εr ไม่มีหน่วย ε มีหน่วย F/m และ D มีหน่วย C/m² อย่าแทน εr แทน ε โดยตรง'),
 ('กรณีประจุคงที่', 'D<sub>n</sub>='+F('Q','S')+' ⇒ E<sub>n</sub>='+F('Q','εS')+'; ε→2ε ⇒ E→E/2', 'ประจุอิสระบนแผ่นคงที่ทำให้ D ถูกตรึง การเพิ่มโพลาไรเซชันจึงลดสนามรวม'),
 ('กรณีแรงดันคงที่', 'E='+F('V','d')+'; Q=εES='+F('εSV','d')+' ⇒ ε→2ε ให้ Q→2Q', 'แหล่งจ่ายส่งประจุเพิ่มเพื่อรักษาแรงดัน จึงไม่ใช่เงื่อนไขเดียวกับกรณีก่อน')],
 ['D=εE ต้องระบุเงื่อนไขตัวกลางเชิงเส้นไอโซทรอปิก', 'ประจุผูกมัดไม่ใช่ประจุอิสระที่ใช้ในเกาส์ของ D', 'ห้ามบอกว่าสนามลดเสมอโดยไม่ระบุ Q คงที่หรือ V คงที่'],
 ['เทฟลอนหรือฉนวนในสายไฟเปลี่ยนความจุและสนามที่รอยต่อ ในงานแรงสูงต้องตรวจความเค้น E พร้อมข้อจำกัดความทนฉนวน ไม่ดู εr อย่างเดียว', 'ช่องอากาศเล็กในฉนวนหลายชั้นอาจมี E สูงกว่าเนื้อวัสดุเมื่อ D ปกติต่อเนื่อง เป็นเหตุให้ต้องศึกษารอยต่อในบทถัดไป'],
 'ใส่ฉนวน εr=2 ในตัวเก็บประจุที่ยังต่อแบตเตอรี่ ประจุและสนามแต่ละอย่างเปลี่ยนอย่างไร?', 'แบบจำลองเชิงเส้น ไอโซทรอปิก ไม่มีความอิ่มตัว การสูญเสีย หรือประวัติการตอบสนอง')

lesson(12, [
 'สนามที่รอยต่อไม่สามารถกระโดดแบบเลือกเอง เพราะวงงานเล็กและกล่องฟลักซ์เล็กต้องรักษากฎสนาม หากสนามสัมผัสสองฝั่งต่างกัน วงที่บางจนแทบไม่มีพื้นที่จะยังมีงานสุทธิ ซึ่งขัดกับไฟฟ้าสถิต',
 'ในตัวนำสมดุล ประจุอิสระจะเคลื่อนทันทีหากมี E ตามผิว แล้วสะสมจนส่วนสัมผัสหายไป ตัวนำจึงเป็นผิวศักย์คงที่และสนามภายนอกตั้งฉากผิว หากยังมีกระแสในตัวนำจริง เงื่อนไขสนามภายในศูนย์ของไฟฟ้าสถิตใช้ไม่ได้',
 'ส่วนปกติของ D กระโดดได้เท่าประจุอิสระบนรอยต่อ แต่ E ปกติไม่จำเป็นต้องเท่ากัน เมื่อไม่มีประจุผิว D ปกติต่อเนื่องและตัวกลางที่ ε ต่ำกว่ามี E ปกติสูงกว่า'], [
 ('สูตรทั่วไปสองกฎ', '∮<sub>C</sub><b>E</b> • d<b>l</b>=0; ∯<sub>S</sub><b>D</b> • d<b>s</b>=Q<sub>free,enc</sub>', 'ใช้ไฟฟ้าสถิตและกำหนดปกติร่วม n จากตัวกลาง 1 ไป 2 ก่อนเลือกวงและผิว'),
 ('วางวงสี่เหลี่ยมคร่อมรอยต่อ', 'E<sub>t1</sub>Δl−E<sub>t2</sub>Δl+O(Δh)=0', 'ด้านยาวเดินสวนกันจึงติดลบ ส่วนด้านสั้นแปรตามความสูง Δh เมื่อสนามมีค่าจำกัด'),
 ('ให้ความสูงเข้าใกล้ศูนย์', 'Δh→0 ⇒ (E<sub>t1</sub>−E<sub>t2</sub>)Δl=0 ⇒ <b>E</b><sub>t1</sub>=<b>E</b><sub>t2</sub>', 'วงบางสามารถหันตามทิศสัมผัสใดก็ได้ จึงเท่ากันทั้งองค์ประกอบสัมผัส'),
 ('วางกล่องยาบาง', 'D<sub>n2</sub>ΔS−D<sub>n1</sub>ΔS+O(Δh)=ρ<sub>s,free</sub>ΔS', 'ฝาบนชี้ +n และฝาล่าง −n ด้านข้างหายเมื่อกล่องบาง แต่ประจุผิวยังคงเท่ากับ ρsΔS'),
 ('หารพื้นที่และใช้เงื่อนไขตัวกลาง', 'D<sub>n2</sub>−D<sub>n1</sub>=ρ<sub>s,free</sub><br>ρ<sub>s,free</sub>=0 ⇒ ε<sub>2</sub>E<sub>n2</sub>=ε<sub>1</sub>E<sub>n1</sub>', 'ตัวห้อยต้องสอดคล้องกับปกติร่วม หากเลือก n จาก 2 ไป 1 ต้องกลับลำดับผลต่างด้วย'),
 ('หามุมจากปกติ', 'tanθ<sub>1</sub>='+F('E<sub>t</sub>','E<sub>n1</sub>')+'; tanθ<sub>2</sub>='+F('E<sub>t</sub>','E<sub>n2</sub>')+' ⇒ '+F('tanθ<sub>1</sub>','tanθ<sub>2</sub>')+'='+F('ε<sub>1</sub>','ε<sub>2</sub>'), 'ใช้ส่วนสัมผัสเดียวกันและ D ปกติต่อเนื่อง มุมวัดกับปกติจึงได้อัตราส่วนนี้ หากวัดกับผิวอัตราส่วนกลับ'),
 ('กรณีผิวตัวนำ', '<b>E</b><sub>inside</sub>=0 ⇒ <b>E</b><sub>t,out</sub>=0; <b>D</b><sub>out</sub> • '+U('n')+'=ρ<sub>s,free</sub>', 'เลือกปกติออกจากตัวนำเข้าสู่ฉนวน สนามภายนอกเหลือแต่ส่วนปกติ ประจุผิวบวกให้สนามออก'),
 ('ตรวจข้อมูล ALL-Q02', 'E<sub>t1</sub>=45 V/m; D<sub>t1</sub>=(2.1)(8.854×10<sup>−12</sup>)(45)=8.36703×10<sup>−10</sup> C/m²<br>D<sub>n1</sub>=20 C/m²; E<sub>n1</sub>='+F('20','2.1×8.854×10<sup>−12</sup>')+'≈1.07565×10<sup>12</sup> V/m', 'ต้นฉบับเลือกปกติจาก 2 ไป 1 แต่ประจุผิวเป็นศูนย์จึง Dn เท่ากัน รักษาหน่วย C/m² แม้สนามสูงมาก')],
 ['E สัมผัสต่อเนื่องและ D ปกติต่อเนื่องเป็นคนละเงื่อนไข', 'เปลี่ยนปกติต้องกลับลำดับผลต่าง', 'ผิวตัวนำในไฟฟ้าสถิตต่างจากตัวนำที่มีกระแสคงตัวและ E ภายในไม่ศูนย์'],
 ['จุดต่อฉนวนกับอากาศในหม้อแปลงอาจเพิ่มสนามในอากาศ เพราะ ε ต่ำกว่า นี่เป็นเหตุผลที่งานออกแบบต้องลดช่องว่างและพิจารณารูปร่างขอบอิเล็กโทรด', 'รอยต่อชั้นฉนวนในสายกำลังและอุปกรณ์แรงสูงใช้สองเงื่อนไขนี้เพื่อแจกแจงสนามก่อนประเมินการทะลุฉนวน ค่าใน ALL-Q02 เป็นแบบฝึกตามต้นฉบับ ไม่ใช่ค่าปลอดภัยของเทฟลอน'],
 'เมื่อไม่มีประจุผิวและ ε₂=2ε₁ ส่วน E ปกติและสัมผัสด้าน 2 เปลี่ยนจากด้าน 1 อย่างไร?', 'ไฟฟ้าสถิต รอยต่อเรียบเฉพาะที่ สนามจำกัด วัสดุเชิงเส้นไอโซทรอปิก ปกติร่วมในพิสูจน์ชี้ 1 → 2; ข้อ ALL-Q02 เลือก 2 → 1 จึงใช้ผลต่างกลับลำดับ')

lesson(13, [
 'ตัวเก็บประจุเก็บประจุเท่ากันคนละเครื่องหมายบนตัวนำสองชิ้น ต้องใช้แรงดันเท่าใดเพื่อแยกประจุหนึ่งคูลอมบ์เป็นเรื่องรูปทรงและวัสดุ ความจุจึงเป็นอัตราส่วน Q ต่อความต่างศักย์ ไม่ใช่ปริมาณประจุที่มีอยู่เพียงอย่างเดียว',
 'พลังงานเพิ่มขึ้นขณะส่งประจุทีละน้อยเข้าแผ่น เพราะประจุเดิมสร้างแรงต้านมากขึ้น แรงดันไม่ได้เป็นค่าสุดท้ายตลอดกระบวนการ จึงต้องอินทิเกรต q/C จากศูนย์ถึง Q และได้ตัวประกอบหนึ่งส่วนสอง'], [
 ('นิยามทั่วไป', 'C='+F('Q','ΔV')+'; ΔV=−∫<sub>−</sub><sup>+</sup><b>E</b> • d<b>l</b>', 'Q คือขนาดประจุบนแผ่นบวก ไม่ใช้ผลรวมประจุสองแผ่นซึ่งเป็นศูนย์'),
 ('ใช้เกาส์กับแผ่นบวก', 'D<sub>n</sub>S=Q ⇒ E='+F('D','ε')+'='+F('Q','εS'), 'สนามแผ่นขนานสม่ำเสมอเมื่อแผ่นกว้างเทียบกับระยะห่างและละเลยขอบ'),
 ('อินทิเกรตแรงดัน', 'ΔV=Ed='+F('Qd','εS'), 'เลือกขนาดแรงดันจากแผ่นลบไปบวก การเดินสวนสนามทำให้ศักย์เพิ่ม'),
 ('แก้ความจุจากนิยาม', 'C='+F('Q',F('Qd','εS'))+'='+F('εS','d'), 'Q ตัดกันแสดงว่าความจุขึ้นกับเรขาคณิตและวัสดุในแบบจำลองเชิงเส้น'),
 ('สูตรทั่วไปของงานเพิ่มประจุ', 'dW=V(q)dq='+F('q','C')+'dq', 'ใช้ q เป็นประจุระหว่างทาง ไม่แทน Q สุดท้ายก่อนอินทิเกรต'),
 ('อินทิเกรตด้วยมือ', 'W='+F('1','C')+'∫<sub>0</sub><sup>Q</sup>q dq='+F('1','C')+'['+F('q²','2')+']<sub>0</sub><sup>Q</sup>='+F('Q²','2C')+'='+F('CV²','2'), 'C คงที่ระหว่างชาร์จสำหรับวัสดุเชิงเส้นและรูปทรงคงที่ ตัวประกอบครึ่งเกิดจากแรงดันเฉลี่ยที่เพิ่มจากศูนย์'),
 ('อ่านเป็นพลังงานต่อปริมาตร', 'W='+F('1','2')+'εSE²d ⇒ w='+F('W','Sd')+'='+F('1','2')+'εE²='+F('1','2')+'<b>E</b> • <b>D</b>', 'แทน V=Ed กับ C=εS/d แล้วหารปริมาตรช่องว่าง หน่วยเป็น J/m³'),
 ('ตัวอย่างหน่วยครบ', 'ε<sub>r</sub>=2, S=20 cm²=2×10<sup>−3</sup> m², d=1 mm=10<sup>−3</sup> m<br>C=35.416 pF; V=10 V ⇒ Q=354.16 pC; W=1.7708 nJ', 'พื้นที่ต้องยกกำลังสองของตัวแปลง cm จึงเป็น 10⁻⁴ ไม่ใช่ 10⁻²')],
 ['ใช้ความต่างศักย์ระหว่างตัวนำ ไม่ใช่ศักย์จุดเดียว', 'cm² และ mm² ต้องแปลงพื้นที่เป็นกำลังสอง', 'พลังงานของวัสดุไม่เชิงเส้นต้องอินทิเกรต D กับ E แทนใช้ครึ่ง εE² โดยตรง'],
 ['ฉนวนระหว่างขดลวดหม้อแปลงทำให้มีความจุแฝง ซึ่งมีผลต่อการตอบสนองแรงดันกระชาก แม้การออกแบบหลักจะเน้นสนามแม่เหล็ก', 'พลังงานสนามเชื่อมกับแรงดึงระหว่างแผ่น แต่ต้องระบุเงื่อนไข Q หรือ V คงที่ก่อนดิฟเฟอเรนเชียลพลังงาน เพราะแหล่งจ่ายอาจแลกเปลี่ยนงาน'],
 'เมื่อเพิ่ม d เป็นสองเท่า C ลดครึ่ง ถ้า V คงที่ W เปลี่ยนอย่างไร และถ้า Q คงที่ล่ะ?', 'ตัวเก็บประจุแผ่นขนานวัสดุเชิงเส้น ขอบละเลยได้ และพื้นที่คงที่')

lesson(14, [
 'สนามเกิดจากประจุและศักย์ถูกกำหนดโดยตัวนำที่ขอบ ถ้าไม่มีประจุในช่องว่าง ไม่ได้แปลว่าสนามศูนย์ แต่หมายถึงความโค้งของศักย์ตามสมการลาปลาสเป็นศูนย์ เงื่อนไขขอบยังสร้างความชันและสนามได้',
 'ระหว่างแผ่นกว้างสองแผ่น ศักย์เปลี่ยนตาม z เพียงแนวเดียว ลาปลาสจึงบอกว่าเส้นศักย์เป็นเส้นตรง ถ้ามีประจุปริมาตรคงที่ เส้นนี้จะโค้งเป็นพาราโบลา การดูความโค้งจึงช่วยอ่านตำแหน่งแหล่ง'], [
 ('สูตรสนามตั้งต้น', '∇ • <b>D</b>=ρ<sub>v</sub>; <b>D</b>=ε<b>E</b>; <b>E</b>=−∇V', 'สามสมการเชื่อมแหล่ง วัสดุ และศักย์ ใช้ไฟฟ้าสถิตก่อนลดเป็น PDE'),
 ('สมการทั่วไปของศักย์', '−∇ • (ε∇V)=ρ<sub>v</sub>', 'ถ้า ε เปลี่ยนตามตำแหน่ง ต้องเก็บมันไว้ใน divergence ห้ามดึงออกโดยอัตโนมัติ'),
 ('ตัวกลางเนื้อเดียวให้ปัวซง', 'ε คงที่ ⇒ ∇²V=−'+F('ρ<sub>v</sub>','ε')+'; ρ<sub>v</sub>=0 ⇒ ∇²V=0', 'ปัวซงกับลาปลาสต่างที่แหล่งประจุปริมาตร ไม่ใช่มีหรือไม่มีแรงดัน'),
 ('ใช้สมมาตรแผ่นขนาน', F('∂V','∂x')+'='+F('∂V','∂y')+'=0 ⇒ '+F('d²V','dz²')+'=0', 'แผ่นกว้างและศักย์เท่ากันตาม x,y ทำให้เหลือสมการหนึ่งมิติ'),
 ('อินทิเกรตครั้งแรก', F('dV','dz')+'=∫0 dz=c<sub>1</sub>', 'อนุพันธ์ความชันเป็นศูนย์จึงความชันคงที่ เก็บค่าคงตัวแรก'),
 ('อินทิเกรตครั้งที่สอง', 'V(z)=∫c<sub>1</sub>dz=c<sub>1</sub>z+c<sub>2</sub>', 'สมการอันดับสองมีค่าคงตัวสองตัว ต้องมีเงื่อนไขสองแห่งจึงกำหนดครบ'),
 ('แทนขอบทีละแห่ง', 'V(0)=0 ⇒ c<sub>2</sub>=0<br>V(d)=V<sub>0</sub> ⇒ c<sub>1</sub>d=V<sub>0</sub> ⇒ V(z)='+F('V<sub>0</sub>','d')+'z', 'แทนค่าศักย์ที่ผิวตัวนำ ไม่ใช้ขอบที่เดาเพิ่ม หากสลับศักย์แผ่น สนามจะกลับทิศ'),
 ('หาสนามและประจุผิวสองแผ่น', '<b>E</b>=−'+F('V<sub>0</sub>','d')+U('z')+'; <b>D</b>=−'+F('εV<sub>0</sub>','d')+U('z')+'<br>ρ<sub>s,บน</sub>=<b>D</b> • (−'+U('z')+')=+'+F('εV<sub>0</sub>','d')+'; ρ<sub>s,ล่าง</sub>=−'+F('εV<sub>0</sub>','d'), 'ปกติออกจากแผ่นบนเข้าสู่ช่องว่างคือ −z แผ่นล่างคือ +z จึงประจุบนบวกแม้ Ez ลบ'),
 ('ตรวจทั้งขอบและสมการ', F('d²V','dz²')+'=0; V(0)=0; V(d)=V<sub>0</sub>; C='+F('εS','d'), 'ผลต้องผ่านทั้ง PDE และค่าขอบ ไม่ใช่แค่มีรูปเส้นตรง ความจุคืนผลบทก่อน')],
 ['ρv=0 ไม่ได้แปลว่า E=0', 'ε ที่ไม่คงที่ใช้ ∇²V=−ρv/ε โดยตรงไม่ได้', 'อย่าลืมค่าคงตัวหรือสลับปกติสองแผ่นในการหาประจุผิว'],
 ['การออกแบบอิเล็กโทรดแรงสูงเริ่มจากศักย์ขอบและคำนวณสนามในฉนวน จากนั้นตรวจตำแหน่งที่ |∇V| สูงซึ่งเสี่ยงต่อความเค้นฉนวน', 'แบบจำลองหนึ่งมิติช่วยตั้งความคาดหมายก่อนใช้วิธีคำนวณสนามสองหรือสามมิติ ในบทนี้ใช้ขอบแผ่นขนานตาม Set 14 ไม่เพิ่ม Uniqueness Theorem ที่คำชี้แจงระบุว่าไม่ได้สอน'],
 'ถ้าแผ่นทั้งสองมีศักย์เท่ากัน ในแบบจำลองนี้ V กับ E เป็นอย่างไร?', 'ไฟฟ้าสถิต ε คงที่ ช่องว่างไร้ประจุ แผ่นกว้างละเลยขอบ')

lesson(15, [
 'กระแสแต่ละส่วนเล็กสร้างสนามแม่เหล็กที่วนรอบแนวการไหล สนามไม่ได้ชี้จากลวดตรงมายังผู้รับแบบไฟฟ้า ผลคูณไขว้จึงเลือกลูกศรที่ตั้งฉากทั้งทิศกระแสและเวกเตอร์ระยะ',
 'ลวดตรงยาวอนันต์ไม่มีปลายและไม่มีมุมรอบแกนที่พิเศษ ทุกส่วนให้สนามทิศ ϕ เดียวกันที่จุดสังเกต แต่ส่วนที่ไกลตาม z มีผลอ่อนลง ปริพันธ์รวมส่วนเหล่านั้นให้การลดแบบหนึ่งส่วนรัศมี'], [
 ('กฎบิโอต์–ซาวารต์ทั่วไป', 'd<b>H</b>='+F('I d<b>l</b>′ × '+U('R'),'4πR²')+'='+F('I d<b>l</b>′ × <b>R</b>','4πR³'), 'กฎเป็นจุดตั้งต้นเชิงกายภาพของแม่เหล็กสถิต รูปสองแบบเท่ากันเมื่อแทนฐานระยะ R/R'),
 ('เรขาคณิตของลวดบนแกน z', 'd<b>l</b>′=dz′'+U('z')+'; <b>R</b>=ρ'+U('ρ')+'−z′'+U('z')+'; R²=ρ²+z′²', 'จุดสังเกตอยู่ z=0 เลือกแกนแหล่ง z′ และกระแสทิศ +z'),
 ('กระจายผลคูณไขว้', 'd<b>l</b>′ × <b>R</b>=dz′[ρ('+U('z')+' × '+U('ρ')+')−z′('+U('z')+' × '+U('z')+')]=ρdz′'+U('ϕ'), 'z×ρ=ϕ และ z×z=0 แสดงทิศก่อนอินทิเกรต ไม่เดาทิศหลังได้ขนาด'),
 ('ตั้งปริพันธ์ทั้งลวด', '<b>H</b>='+F('Iρ','4π')+U('ϕ')+'∫<sub>−∞</sub><sup>∞</sup>'+F('dz′','(ρ²+z′²)<sup>3/2</sup>'), 'I กับ ρ และฐานที่จุดสังเกตคงที่ขณะรวม z′ จึงออกนอกปริพันธ์ได้'),
 ('แทนตัวแปรและเปลี่ยนขอบ', 'z′=ρtanψ; dz′=ρsec²ψdψ; (ρ²+z′²)<sup>3/2</sup>=ρ³sec³ψ<br>z′:−∞→∞ ⇒ ψ:−π/2→π/2', 'ρ>0 และ cosψ เป็นบวกในช่วงนี้ จึงลดรากกำลังสามได้โดยไม่ทำเครื่องหมายผิด'),
 ('อินทิเกรตด้วยมือ', '∫<sub>−∞</sub><sup>∞</sup>'+F('dz′','(ρ²+z′²)<sup>3/2</sup>')+'='+F('1','ρ²')+'∫<sub>−π/2</sub><sup>π/2</sup>cosψdψ='+F('1','ρ²')+'[sinψ]<sub>−π/2</sub><sup>π/2</sup>='+F('2','ρ²'), 'sec² จากดิฟเฟอเรนเชียลหาร sec³ เหลือ cos และค่าปลายเป็น 1−(−1)=2'),
 ('คืนตัวประกอบและตรวจหน่วย', '<b>H</b>='+F('Iρ','4π')+F('2','ρ²')+U('ϕ')+'='+F('I','2πρ')+U('ϕ')+' A/m; <b>B</b>=μ<b>H</b>', 'ρ ตัดไปหนึ่งกำลัง กระแสกลับทิศทำให้สนามกลับ ไม่คูณ μ หากโจทย์ถาม H'),
 ('ขอบเขตการใช้สูตร', 'ρ>0; I→−I ⇒ <b>H</b>→−<b>H</b>', 'สูตรลวดเส้นอุดมคติไม่อธิบายสนามภายในตัวนำรัศมีจริง และลวดจำกัดต้องใช้ขอบจำกัด')],
 ['H หน่วย A/m ส่วน B หน่วย T ห้ามผสม μ ลงใน H', 'dล × R สลับลำดับแล้วทิศกลับ', 'แสดงการเปลี่ยนขอบและเอกลักษณ์ตรีโกณมิติใน ALL-Q04'],
 ['สนามรอบบัสบาร์กำหนดแรงแม่เหล็กระหว่างตัวนำกำลัง และการวางตัวนำส่งผลต่อแรงขณะลัดวงจร สูตรลวดอนันต์เป็นประมาณการเมื่ออยู่ห่างปลาย', 'ผลเดียวกันจะหาได้สั้นกว่าด้วยแอมแปร์ในบทถัดไป แต่การพิสูจน์นี้ทำให้รู้ว่าความสมมาตรและลวดยาวเป็นเงื่อนไข ไม่ใช่ข้อจริงของทุกตัวนำ'],
 'ถ้ากลับกระแสเป็น −z แต่ตำแหน่งเดิม ทิศสนามต้องเปลี่ยนอย่างไร? ใช้ผลคูณไขว้ตรวจ', 'กระแสสถิตลวดตรงอนันต์เส้นเล็ก จุดสังเกตไม่อยู่บนแกน')

lesson(16, [
 'แอมแปร์วัดยอดการวนของ H รอบวง แล้วเทียบกับกระแสที่แทงผ่านผิวภายในวง การวนเป็นการสะสมส่วนสัมผัสตลอดทาง ไม่ใช่ดูสนามที่จุดเดียว กฎจริงทุกวงในแม่เหล็กสถิต แต่หา H ง่ายเมื่อสมมาตรทำให้ขนาดคงที่ตามวง',
 'ในลวดตันกระแสสม่ำเสมอ วงเล็กภายในล้อมกระแสเพียงสัดส่วนพื้นที่ จึง H เพิ่มตามรัศมี ภายนอกล้อมกระแสครบแล้ว แต่เส้นรอบวงโตขึ้น H จึงลดตามรัศมี สนามต่อเนื่องที่ผิวในแบบจำลองนี้'], [
 ('กฎทั่วไปและทิศวง', '∮<sub>C</sub><b>H</b> • d<b>l</b>=I<sub>enc</sub>=∫<sub>S</sub><b>J</b> • d<b>s</b>', 'ปกติผิวกับทิศเดินวงต้องจับคู่ด้วยมือขวา และใช้รูปนี้เฉพาะแม่เหล็กสถิต'),
 ('เลือกวงตามสมมาตร', 'ρ คงที่; d<b>l</b>=ρdϕ'+U('ϕ')+'; <b>H</b>=H<sub>ϕ</sub>(ρ)'+U('ϕ'), 'วงกลมร่วมแกนทำให้สนามสัมผัสวงและขนาดไม่ขึ้นกับ ϕ จึงดึง Hϕ ออกได้'),
 ('อินทิเกรตวงด้วยมือ', '∮<sub>C</sub><b>H</b> • d<b>l</b>=H<sub>ϕ</sub>ρ∫<sub>0</sub><sup>2π</sup>dϕ=2πρH<sub>ϕ</sub>', 'ฐานเดียวกัน dot เท่ากับหนึ่ง แล้วประเมิน [ϕ] จาก 0 ถึง 2π'),
 ('ความหนาแน่นกระแสในลวดตัน', 'J<sub>z</sub>='+F('I','πa²'), 'a เป็นรัศมีลวดจริง แยกจาก ρ ที่เป็นรัศมีวงทดลอง'),
 ('กระแสที่ล้อมภายใน', 'ρ≤a: I<sub>enc</sub>=∫<sub>0</sub><sup>2π</sup>∫<sub>0</sub><sup>ρ</sup>J<sub>z</sub>ρ′dρ′dϕ=J<sub>z</sub>(2π)'+F('ρ²','2')+'='+F('Iρ²','a²'), 'ใช้พื้นที่หน้าตัดที่วงล้อมจริง ไม่แทน I รวมเมื่อยังอยู่ในลวด'),
 ('สนามสองบริเวณ', 'ρ≤a: H<sub>ϕ</sub>='+F('Iρ','2πa²')+'<br>ρ≥a: H<sub>ϕ</sub>='+F('I','2πρ'), 'ภายในกระแสโตตาม ρ² หารเส้นรอบวงตาม ρ จึงเหลือเพิ่มตาม ρ ภายนอกกระแสคงที่'),
 ('ตรวจจุดศูนย์กลางและผิว', 'H<sub>ϕ</sub>(0)=0; H<sub>ϕ</sub>(a<sup>−</sup>)=H<sub>ϕ</sub>(a<sup>+</sup>)='+F('I','2πa'), 'ตรวจความต่อเนื่องและไม่เกิดเอกฐานในลวดตัน ต่างจากแบบจำลองเส้นลวดที่ไม่มีรัศมี'),
 ('ALL-Q05 ต่อ ALL-Q06', '<b>H</b>='+F('K','2πρ')+U('ϕ')+' ⇒ I<sub>enc</sub>=∫<sub>0</sub><sup>2π</sup>'+F('K','2πρ')+'ρdϕ='+F('K','2π')+'[ϕ]<sub>0</sub><sup>2π</sup>=K', 'สองป้ายในไฟล์เป็นตัวอย่างเดียวกัน K หน่วย A ถ้า K บวกกระแสตาม +z ถ้าลบตาม −z')],
 ['กฎแอมแปร์จริงไม่ได้ทำให้ดึง H ออกได้ทุกวง', 'ภายในลวดใช้ Ienc ไม่ใช้ I รวม', 'วงกลับทิศต้องกลับปกติและเครื่องหมายกระแสที่ล้อมด้วย'],
 ['ลวดตันและบัสบาร์แสดงการกระจาย H ภายในกับภายนอก จุดสูงสุดในแบบจำลองสม่ำเสมออยู่ที่ผิว เมื่อความถี่สูง skin effect ทำให้ J ไม่สม่ำเสมอและต้องเปลี่ยนแบบจำลอง', 'แกนวงแหวนในเครื่องจักรและหม้อแปลงใช้วงตามสมมาตรเพื่อเชื่อมแอมแปร์กับแรงแม่เหล็ก NI แต่การประมาณสนามคงที่ตามแกนต้องตรวจช่องอากาศและรูปทรงจริง'],
 'เพราะเหตุใดสูตรนอกลวดที่มี 1/ρ จึงใช้ถึง ρ=0 ไม่ได้ในตัวนำตัน?', 'แม่เหล็กสถิต ลวดอนันต์ J สม่ำเสมอ ไม่มีผล skin หรือ proximity')

lesson(17, [
 'curl ไม่ใช่ความโค้งของเส้นสนาม แต่คือการวนสุทธิต่อพื้นที่ของวงเล็ก สนามเส้นตรงที่มีขนาดต่างกันคนละด้านของวงก็มี curl ได้ ส่วนสนามที่มองเห็นเป็นวงอาจมี curl ศูนย์นอกจุดแหล่ง การดูรูปร่างอย่างเดียวจึงไม่พอ',
 'เอาวงเล็กมาต่อกัน การเดินบนขอบร่วมสวนกันจึงตัดกัน เหลือขอบนอกเพียงวงเดียว เป็นเหตุให้ผลรวม curl ทั่วผิวเท่ากับการวนบนขอบตามสโตกส์ และทิศปกติต้องคู่กับทิศวงด้วยมือขวา'], [
 ('นิยามการวนต่อพื้นที่', '(∇ × <b>H</b>) • '+U('n')+'=lim<sub>ΔS→0</sub>'+F('∮<sub>∂ΔS</sub><b>H</b> • d<b>l</b>','ΔS'), 'นิยามได้องค์ประกอบ curl ตามปกติของวง ไม่ใช่ค่า curl ทั้งเวกเตอร์จากวงเดียว'),
 ('วงเล็กในระนาบ xy', '∮<b>H</b> • d<b>l</b>≈[H<sub>y</sub>(x+Δx)−H<sub>y</sub>(x)]Δy−[H<sub>x</sub>(y+Δy)−H<sub>x</sub>(y)]Δx', 'เดินทวนเข็มเมื่อมองจาก +z คู่ด้านแนว y ให้พจน์บวก คู่ด้านแนว x ให้พจน์ลบ'),
 ('หารพื้นที่แล้วให้วงเล็กลง', '(∇ × <b>H</b>)<sub>z</sub>='+F('∂H<sub>y</sub>','∂x')+'−'+F('∂H<sub>x</sub>','∂y'), 'ΔxΔy ตัดออก อนุพันธ์แสดงความต่างสนามระหว่างด้านคู่ของวง'),
 ('ประกอบอีกสองระนาบ', '∇ × <b>H</b>=('+F('∂H<sub>z</sub>','∂y')+'−'+F('∂H<sub>y</sub>','∂z')+')'+U('x')+'+('+F('∂H<sub>x</sub>','∂z')+'−'+F('∂H<sub>z</sub>','∂x')+')'+U('y')+'+('+F('∂H<sub>y</sub>','∂x')+'−'+F('∂H<sub>x</sub>','∂y')+')'+U('z'), 'วนลำดับ x,y,z ให้ครบ สูตรนี้แสดงอนุพันธ์ทุกคู่ก่อนแทนข้อมูล'),
 ('เชื่อมกับกระแสในแม่เหล็กสถิต', '∮<b>H</b> • d<b>l</b>=∫<b>J</b> • d<b>s</b> ⇒ ∇ × <b>H</b>=<b>J</b>', 'แอมแปร์จริงทุกวงเล็กจึงเทียบการวนต่อพื้นที่กับความหนาแน่นกระแสต่อพื้นที่ได้'),
 ('คำนวณ ALL-Q07 ก่อนแทนจุด', 'H<sub>x</sub>=0; H<sub>y</sub>=x²z; H<sub>z</sub>=−y²x<br>J<sub>x</sub>=−2yx−x²; J<sub>y</sub>=0−(−y²)=y²; J<sub>z</sub>=2xz−0=2xz', 'หาอนุพันธ์ฟังก์ชันก่อน หากแทน P ก่อน สนามจะกลายเป็นค่าคงที่และอนุพันธ์ผิดเป็นศูนย์'),
 ('แทนจุดและตรวจด้วยเอกลักษณ์', '<b>J</b>(2,3,4)=−16'+U('x')+'+9'+U('y')+'+16'+U('z')+' A/m²<br>∇ • <b>J</b>=−2y+2y+0=0', 'หน่วย H หารระยะเป็น A/m² และ divergence ของ curl ต้องเป็นศูนย์ในสนามเรียบ'),
 ('สโตกส์จากการรวมวงเล็ก', '∮<sub>∂S</sub><b>H</b> • d<b>l</b>=∫<sub>S</sub>(∇ × <b>H</b>) • d<b>s</b>', 'ขอบร่วมของวงย่อยหักล้าง เหลือขอบนอก กฎนี้เป็นเรขาคณิตของตัวดำเนินการ ไม่ใช่กฎวัสดุ'),
 ('ตัวอย่างตรวจสองด้านโดยตรง', '<b>H</b>=kx'+U('y')+'; 0≤x,y≤a ⇒ ∇ × <b>H</b>=k'+U('z')+'<br>∮<b>H</b> • d<b>l</b>=ka·a=ka²; ∫<sub>S</sub>k ds=ka²', 'ด้านขวาของวงมี Hy=ka ด้านซ้ายศูนย์ อีกสองด้าน dot เป็นศูนย์ ผลตรงกับ curl คูณพื้นที่')],
 ['อย่าตีความว่าเส้นสนามโค้งแปลว่า curl ไม่ศูนย์เสมอ', 'สูตรดีเทอร์มิแนนต์ในพิกัดโค้งต้องมีตัวประกอบสเกล', 'สโตกส์ต้องจับคู่ปกติกับทิศวง อย่าสลับฝ่ายเดียว'],
 ['การคำนวณ J จาก H ใช้ตรวจสนามแม่เหล็กในแบบจำลองตัวนำว่าตรงกับแหล่งกระแสที่ตั้งไว้หรือไม่', 'การวนของสนามไฟฟ้าในบทฟาราเดย์จะทำให้แรงดันขึ้นกับวงและฟลักซ์ ซึ่งเป็นฐานแรงดันเหนี่ยวนำในขดลวดหม้อแปลง'],
 'H=kx ay มีเส้นสนามตรง แต่ curl ไม่ศูนย์ได้อย่างไร? อธิบายจากความต่างสองด้านของวง', 'สนามเรียบ ผิววางทิศได้และขอบคู่ตามมือขวา; ∇×H=J ใช้แม่เหล็กสถิต')

lesson(18, [
 'B วัดฟลักซ์แม่เหล็กต่อพื้นที่ ส่วน H เชื่อมกับแหล่งกระแส ตัวกลางเดียวกันอาจให้ B เพิ่มเมื่อ H เพิ่ม แต่เหล็กจริงไม่จำเป็นต้องมี μ คงที่ การใช้ B=μH จึงเป็นแบบจำลองที่ต้องระบุ',
 'เส้นสนามแม่เหล็กไม่เริ่มหรือจบแบบประจุไฟฟ้าในแบบจำลองคลาสสิก ฟลักซ์ที่เข้าในผิวปิดจึงออกเท่ากัน แม้ผิวเปิดหน้าขดลวดจะมีฟลักซ์มากและใช้สร้างแรงดันเหนี่ยวนำได้'], [
 ('นิยามฟลักซ์แม่เหล็กทั่วไป', 'Φ=∫<sub>S</sub><b>B</b> • d<b>s</b>', 'ใช้ B ไม่ใช้ H หน่วย T·m² เป็น Wb ผิวเปิดต้องเลือกปกติเพื่อกำหนดเครื่องหมาย'),
 ('วัสดุเชิงเส้นและฟลักซ์ผิวแบน', '<b>B</b>=μ<b>H</b>; μ=μ<sub>0</sub>μ<sub>r</sub><br>Φ=BS cosθ=μHS cosθ', 'ดึงสนามและมุมออกได้เมื่อคงที่ทั่วผิว θ วัดกับปกติไม่ใช่กับผิว'),
 ('กฎเกาส์แม่เหล็ก', '∯<sub>∂v</sub><b>B</b> • d<b>s</b>=0', 'เป็นกฎสนามพื้นฐานว่าไม่มีแหล่งประจุแม่เหล็กในแบบจำลองนี้ ไม่ได้บอกว่า B เป็นศูนย์'),
 ('ใช้ทฤษฎีบทไดเวอร์เจนซ์', '∫<sub>v</sub>(∇ • <b>B</b>)dv=0 สำหรับทุก v ⇒ ∇ • <b>B</b>=0', 'กฎผิวปิดจริงกับทุกปริมาตรจึงคืนรูปจุดได้'),
 ('ศักย์เวกเตอร์เป็นการอ่านต่อยอด', '<b>B</b>=∇ × <b>A</b> ⇒ ∇ • <b>B</b>=∇ • (∇ × <b>A</b>)=0', 'ในบริเวณที่เงื่อนไขความเรียบและโทโพโลยีเหมาะสม สามารถใช้ศักย์เวกเตอร์สร้างสนาม divergence ศูนย์ ห้ามสับสนกับศักย์สเกลาร์ V'),
 ('ความไม่เป็นเอกลักษณ์ของ A', '<b>A</b>′=<b>A</b>+∇χ ⇒ ∇ × <b>A</b>′=∇ × <b>A</b>+∇ × ∇χ=<b>B</b>', 'การเพิ่มเกรเดียนต์ไม่เปลี่ยน curl จึง A ไม่ใช่สนาม B และต้องกำหนด gauge เมื่อแก้บางปัญหา'),
 ('เปลี่ยนผิวเปิดเป็นวงขอบ', 'Φ=∫<sub>S</sub>(∇ × <b>A</b>) • d<b>s</b>=∮<sub>∂S</sub><b>A</b> • d<b>l</b>', 'ใช้สโตกส์และคู่ทิศเดียวกัน หน่วย A ต้องเป็น Wb/m เพื่ออินทิเกรตตามความยาวแล้วได้ Wb'),
 ('ตรวจด้วยค่าจริงและมุม', 'B=0.2 T; S=0.03 m²; θ=60° ⇒ Φ=(0.2)(0.03)(0.5)=3×10<sup>−3</sup> Wb', 'ถ้ากลับปกติ θ เป็น 120° ฟลักซ์เป็น −3 mWb แต่ B จริงยังเดิม')],
 ['ฟลักซ์ผิวปิดศูนย์ไม่ได้แปลว่าฟลักซ์ทุกผิวเปิดศูนย์', 'μr ไม่มีหน่วยและไม่ใช่ μ', 'μ คงที่ไม่อธิบายความอิ่มตัวหรือฮิสเทอรีซิสของแกนเหล็กจริง'],
 ['หม้อแปลงใช้ฟลักซ์ผ่านหน้าขดลวด ไม่ใช้ยอดสุทธิผิวปิดที่เป็นศูนย์ การเลือกพื้นที่และปกติถูกต้องจึงเชื่อมกับเครื่องหมายแรงดันได้', 'ศักย์เวกเตอร์เป็นเครื่องมือของวิธีคำนวณสนามหลายแบบ เนื้อหานี้แยกเป็นการต่อยอด ไม่อนุมานว่า gauge หรือรายละเอียดวิธีตัวเลขเป็นข้อสอบทางการ'],
 'แม่เหล็กแท่งอยู่ในกล่อง ฟลักซ์ B สุทธิออกกล่องเท่าใด? แล้วผ่านฝากล่องหน้าเดียวอาจไม่ศูนย์หรือไม่?', 'ตัวอย่าง B=μH ใช้วัสดุเชิงเส้นไอโซทรอปิก สนามสม่ำเสมอทั่วผิวเปิด')

lesson(19, [
 'สมการแมกซ์เวลล์สถิตเป็นบัญชีแหล่งและการวนสองชุด ไฟฟ้ามีประจุเป็นแหล่งแต่ไม่มีการวน แม่เหล็กไม่มีแหล่งเดี่ยวแต่มีการวนจากกระแส การรู้สมการทั้งสี่ช่วยแยกว่าสนามที่เสนอถูกกายภาพหรือผ่านเพียงสมการบางข้อ',
 'สมการสนามไม่กำหนดคำตอบหนึ่งเดียวโดยไม่รู้วัสดุ แหล่ง และเงื่อนไขขอบ การให้เพียง divergence กับ curl จึงยังไม่ใช่โจทย์หาสนามที่สมบูรณ์ ต้องตรวจด้วยว่าสภาวะสถิตสอดคล้องกับแหล่ง'], [
 ('กฎทั่วไปในรูปอินทิกรัล', '∯<b>D</b> • d<b>s</b>=Q<sub>free,enc</sub>; ∮<b>E</b> • d<b>l</b>=0<br>∯<b>B</b> • d<b>s</b>=0; ∮<b>H</b> • d<b>l</b>=I<sub>enc</sub>', 'ผิวปิดใช้ปกติออก วงกับผิวของสองกฎวงต้องตามมือขวา'),
 ('กฎแหล่งไฟฟ้า', '∫<sub>v</sub>(∇ • <b>D</b>)dv=∫<sub>v</sub>ρ<sub>v</sub>dv ⇒ ∇ • <b>D</b>=ρ<sub>v</sub>', 'divergence theorem เปลี่ยนฟลักซ์เป็นแหล่งที่จุด เมื่อจริงทุกปริมาตรจึงเทียบอินทิแกรนด์'),
 ('กฎไม่มีการวนไฟฟ้าสถิต', '∫<sub>S</sub>(∇ × <b>E</b>) • d<b>s</b>=0 ⇒ ∇ × <b>E</b>=0', 'สโตกส์เปลี่ยนวงเป็น curl ในบริเวณที่เหมาะสมจึงนิยาม E=−∇V ได้'),
 ('กฎไม่มีแหล่งแม่เหล็ก', '∫<sub>v</sub>(∇ • <b>B</b>)dv=0 ⇒ ∇ • <b>B</b>=0', 'อย่าเปลี่ยนเป็น divergence H ศูนย์โดยไม่ตรวจ μ ถ้า μ เปลี่ยนตามตำแหน่ง'),
 ('กฎการวนแม่เหล็ก', '∫<sub>S</sub>(∇ × <b>H</b>) • d<b>s</b>=∫<sub>S</sub><b>J</b> • d<b>s</b> ⇒ ∇ × <b>H</b>=<b>J</b>', 'เทียบทุกผิวและใช้แหล่งกระแสสถิต'),
 ('เพิ่มสมการตัวกลาง', '<b>D</b>=ε<b>E</b>; <b>B</b>=μ<b>H</b>; <b>J</b>=σ<b>E</b>', 'กฎแมกซ์เวลล์เป็นกฎสนาม ส่วนสามความสัมพันธ์นี้เป็นแบบจำลองวัสดุ ไม่ใช่กฎเดียวกัน'),
 ('ตรวจความสอดคล้องของกระแส', '∇ • <b>J</b>=∇ • (∇ × <b>H</b>)=0', 'สภาวะสถิตห้ามมีประจุสะสมต่อเวลา การใช้กระแส divergence ไม่ศูนย์กับสมการสถิตจึงขัดกัน'),
 ('ตัวอย่างตรวจทั้งสองบทบาท', '<b>D</b>=kx'+U('x')+' ⇒ ρ<sub>v</sub>=k; <b>H</b>=hy'+U('z')+' ⇒ <b>J</b>=h'+U('x'), 'สองสนามนี้เป็นตัวอย่างตรวจตัวดำเนินการแยกกัน ไม่ใช่คู่สนามที่ยืนยันครบในวัสดุนำเดียวกัน การจับคู่จริงต้องตรวจสมการตัวกลางและขอบด้วย')],
 ['อย่าใช้สมการสถิตกับฟลักซ์เปลี่ยนเวลา', 'gauge หรือศูนย์ศักย์ไม่แทนเงื่อนไขขอบจริง', 'divergence B ศูนย์ไม่เท่ากับ divergence H ศูนย์ในทุกวัสดุ'],
 ['แบบจำลองสนามไฟฟ้าของฉนวนและสนามแม่เหล็กรอบกระแส DC แยกแก้ได้ในสภาวะสถิต แต่ต้องใช้วัสดุและขอบที่ตรงอุปกรณ์', 'ก่อนศึกษาหม้อแปลงต้องเปลี่ยนสมการ curl E เพราะฟลักซ์เปลี่ยนเวลา สมการสถิตเพียงชุดนี้อธิบายแรงดันเหนี่ยวนำไม่ได้'],
 'ถ้ามี J ที่ divergence เป็นบวกต่อเนื่อง จะเป็นสภาวะประจุสถิตได้หรือไม่?', 'แหล่งและสนามไม่เปลี่ยนเวลา วัสดุเชิงเส้นตามความสัมพันธ์ที่ระบุ')

lesson(20, [
 'ฟลักซ์แม่เหล็กที่เปลี่ยนทำให้สนามไฟฟ้าวนได้ จึงมีงานต่อประจุรอบวงแม้กลับมาจุดเดิม แรงดันเหนี่ยวนำไม่ใช่ความต่างของศักย์สเกลาร์เพียงสองจุดในทุกสถานการณ์ ต้องระบุวงและขอบเขตฟลักซ์',
 'เครื่องหมายลบของเลนซ์บอกว่าการตอบสนองต้านการเปลี่ยนฟลักซ์ต้นเหตุ ไม่ใช่ต้าน B เสมอ ถ้า B กำลังลด กระแสเหนี่ยวนำจะช่วยรักษา B ทิศเดิม ถ้าสมมติให้มันเสริมการเพิ่ม จะขยายฟลักซ์และกระแสเองโดยไม่รับงานเพิ่ม ขัดกับบัญชีพลังงานของระบบพาสซีฟ',
 'วงที่อยู่นิ่งรับสนามแปรเวลา กับวงที่เคลื่อนผ่านสนามคงที่เป็นคนละกลไก ส่วนแรกมาจาก curl E ส่วนหลังมาจากแรง qv×B ต้องเลือกสูตรให้ตรงสถานการณ์'], [
 ('ฟาราเดย์ทั่วไปสำหรับวงอยู่นิ่ง', 'ℰ=∮<sub>C</sub><b>E</b> • d<b>l</b>=−'+F('d','dt')+'∫<sub>S</sub><b>B</b> • d<b>s</b>', 'เลือกปกติผิวกับวงตามมือขวา วงและผิวคงที่จึงย้ายอนุพันธ์ผ่านปริพันธ์ผิวได้'),
 ('ย้ายอนุพันธ์และใช้สโตกส์', '∫<sub>S</sub>(∇ × <b>E</b>) • d<b>s</b>=−∫<sub>S</sub>'+F('∂<b>B</b>','∂t')+' • d<b>s</b>', 'อนุพันธ์ย่อยถือจุดสังเกตคงที่ ใช้ทุกผิวที่อยู่นิ่ง'),
 ('คืนรูปจุด', '∇ × <b>E</b>=−'+F('∂<b>B</b>','∂t')+'=−μ'+F('∂<b>H</b>','∂t'), 'รูปสุดท้ายใช้ μ คงที่ตามเวลา ถ้าวัสดุเปลี่ยนต้องคงอนุพันธ์ B เต็มไว้'),
 ('หลายรอบกับฟลักซ์เชื่อมโยง', 'λ<sub>flux</sub>=NΦ; ℰ=−'+F('dλ<sub>flux</sub>','dt')+'=−N'+F('dΦ','dt'), 'แต่ละรอบรับฟลักซ์เดียวกันและ N คงที่ สัญลักษณ์นี้เป็นฟลักซ์เชื่อมโยงไม่ใช่ความยาวคลื่น'),
 ('ตัวอย่างฟลักซ์ไซน์', 'Φ(t)=Φ<sub>0</sub>cosωt ⇒ '+F('dΦ','dt')+'=−ωΦ<sub>0</sub>sinωt ⇒ ℰ=NωΦ<sub>0</sub>sinωt', 'ลบของฟาราเดย์กับลบจากอนุพันธ์ cos ตัดกัน ใช้กฎลูกโซ่จึงต้องมี ω'),
 ('เชื่อมกับขนาดที่อ่านได้', 'N=100; f=50 Hz; Φ<sub>0</sub>=2 mWb ⇒ ω=2πf=100π rad/s<br>ℰ<sub>peak</sub>=100(100π)(0.002)=62.832 V', 'แปลง mWb เป็น Wb ก่อนแทน ผลเป็น peak ไม่ใช่ RMS'),
 ('ALL-Q08 กระจาย curl E', 'E<sub>x</sub>=A cosωt sinκy ⇒ (∇ × <b>E</b>)<sub>z</sub>=−'+F('∂E<sub>x</sub>','∂y')+'=−Aκ cosωt cosκy', 'สนามมีแต่ x และขึ้นกับ y เครื่องหมายองค์ประกอบ z มาจาก −∂Ex/∂y'),
 ('อินทิเกรต H ตามเวลา', F('∂H<sub>z</sub>','∂t')+'='+F('Aκ','μ')+'cosωt cosκy ⇒ H<sub>z</sub>='+F('Aκ','μω')+'sinωt cosκy+H<sub>z,static</sub>(y)', 'อินทิเกรต cosωt ให้ sinωt/ω และเก็บส่วนสถิตไว้ คำตอบตัวอย่างเลือกส่วนสถิตศูนย์'),
 ('ค่าสัมประสิทธิ์ต้นฉบับ', 'A=20×10<sup>−4</sup> V/m; κ=10<sup>−3</sup> m<sup>−1</sup>; μ=10<sup>−5</sup> H/m; ω=10<sup>5</sup> rad/s<br><b>H</b>=2×10<sup>−6</sup>sin(10<sup>5</sup>t)cos(10<sup>−3</sup>y)'+U('z')+' A/m', 'สไลด์ใช้ A=2×10⁻⁴ จึงได้ H เล็กกว่าสิบเท่า ต้องแยกฉบับให้ชัด'),
 ('กรณีวงเคลื่อน', 'ℰ=∮(<b>E</b>+<b>v</b> × <b>B</b>) • d<b>l</b>', 'รวมแรงต่อประจุจากสนามไฟฟ้าและการเคลื่อนของตัวนำ สูตรฟาราเดย์ของวงอยู่นิ่งไม่ครอบคลุมส่วน motional โดยลำพัง')],
 ['เลนซ์ต้านการเปลี่ยนฟลักซ์ ไม่ใช่ต้านสนามเดิมทุกกรณี', 'cos(ωt) ดิฟเฟอเรนเชียลต้องมี ω', 'คำตอบจากฟาราเดย์เพียงสมการเดียวยังต้องตรวจแมกซ์เวลล์อื่นและแหล่งที่จำเป็น'],
 ['หม้อแปลงมีขดลวดอยู่นิ่งแต่ฟลักซ์แปรเวลา แรงดันแต่ละขดสัมพันธ์กับ N และ dΦ/dt จึงอธิบายอัตราส่วนแรงดันได้เมื่อฟลักซ์เชื่อมโยงร่วม', 'เครื่องกำเนิดสามารถเปลี่ยนฟลักซ์เชื่อมโยงโดยการหมุนวงในสนาม และมอเตอร์มีแรงดันย้อนกลับจากการเคลื่อน การอนุรักษ์พลังงานบอกว่าพลังงานไฟฟ้าที่ได้ต้องมาจากงานกลหรือแหล่งสนาม'],
 'เมื่อฟลักซ์ cosωt อยู่ที่ค่าสูงสุด แรงดันเหนี่ยวนำเป็นศูนย์เพราะเหตุใด?', 'วงอยู่นิ่งในขั้น 1–9; μ คงที่และเลือกส่วนสนามสถิตศูนย์ในตัวอย่างตามสไลด์')

lesson(21, [
 'วงแอมแปร์รอบสายที่กำลังชาร์จตัวเก็บประจุสามารถขึงผิวตัดผ่านลวดหรืออ้อมไปในช่องฉนวนได้ ถ้านับเฉพาะประจุที่วิ่งผ่าน ผิวแรกมีกระแสแต่ผิวที่สองไม่มี ทั้งที่วงเดียวกันต้องให้ยอดการวน H เดียวกัน',
 'D ในช่องฉนวนเปลี่ยนเพราะประจุบนแผ่นสะสม อัตราการเปลี่ยนฟลักซ์ D จึงเติมบัญชีกระแสให้ทั้งสองผิวตรงกัน กระแสการกระจัดไม่แปลว่าอิเล็กตรอนทะลุฉนวน แต่เป็นพจน์สนามที่สร้างผลแม่เหล็กและรักษาการอนุรักษ์ประจุ',
 'การแก้ความไม่สอดคล้องนี้ทำให้สนามไฟฟ้ากับแม่เหล็กเลี้ยงการเปลี่ยนของกันและกัน จึงเตรียมพื้นฐานการแพร่คลื่นในบทถัดไป'], [
 ('ตรวจข้อจำกัดของรูปสถิต', '∇ × <b>H</b>=<b>J</b> ⇒ 0=∇ • (∇ × <b>H</b>)=∇ • <b>J</b>', 'divergence ของ curl เป็นศูนย์เสมอในสนามเรียบ แต่ขณะประจุสะสม continuity ให้ divergence J ไม่ศูนย์'),
 ('ใช้การอนุรักษ์ประจุ', '∇ • <b>J</b>=−'+F('∂ρ<sub>v</sub>','∂t')+'; ρ<sub>v</sub>=∇ • <b>D</b>', 'แทนแหล่งประจุด้วยเกาส์เพื่อหาพจน์ที่หักล้าง divergence ของกระแส'),
 ('สร้างพจน์ที่คืนสมดุล', '∇ • (<b>J</b>+'+F('∂<b>D</b>','∂t')+')=−'+F('∂ρ<sub>v</sub>','∂t')+'+'+F('∂','∂t')+'(∇ • <b>D</b>)=0', 'สลับอนุพันธ์พื้นที่กับเวลาได้เมื่อสนามเรียบ ความสอดคล้องนี้ชี้พจน์ที่ต้องเพิ่ม แต่กฎเต็มยังเป็นกฎสนามพื้นฐาน'),
 ('แอมแปร์–แมกซ์เวลล์เต็ม', '∇ × <b>H</b>=<b>J</b>+'+F('∂<b>D</b>','∂t')+'; <b>J</b><sub>d</sub>≡'+F('∂<b>D</b>','∂t'), 'Jd มีหน่วย C/m² ต่อ s = A/m² ไม่ใช่ความหนาแน่นประจุ'),
 ('เปลี่ยนเป็นรูปวง', '∮<sub>C</sub><b>H</b> • d<b>l</b>=∫<sub>S</sub><b>J</b> • d<b>s</b>+'+F('d','dt')+'∫<sub>S</sub><b>D</b> • d<b>s</b>', 'ใช้สโตกส์และผิวคงที่ ยอดกระแสรวมทำให้ผลไม่ขึ้นกับการขึงผิวที่มีขอบเดียวกัน'),
 ('กระแสลวดของ ALL-Q09', 'q=Cv<sub>c</sub>; v<sub>c</sub>=V<sub>0</sub>cosωt<br>i='+F('dq','dt')+'=CV<sub>0</sub>'+F('d(cosωt)','dt')+'=−ωCV<sub>0</sub>sinωt', 'C คงที่และเครื่องหมายกระแสเข้าขั้วบวกตามข้อตกลงพาสซีฟ'),
 ('สนามในฉนวน', '<b>E</b>='+F('V<sub>0</sub>','d')+'cosωt'+U('n')+'; <b>D</b>='+F('εV<sub>0</sub>','d')+'cosωt'+U('n'), 'เลือกปกติจากแผ่นบวกสู่ลบ ใช้สนามแผ่นขนานและวัสดุคงที่'),
 ('ดิฟเฟอเรนเชียลและอินทิเกรตผิว', '<b>J</b><sub>d</sub>=−'+F('εωV<sub>0</sub>','d')+'sinωt'+U('n')+'<br>I<sub>d</sub>=∫<sub>S</sub><b>J</b><sub>d</sub> • d<b>s</b>=−'+F('εS','d')+'ωV<sub>0</sub>sinωt=−ωCV<sub>0</sub>sinωt=i', 'ฐานปกติ dot เท่ากับหนึ่งและสนามสม่ำเสมอจึงคูณพื้นที่ ใช้ C=εS/d หลังแสดงปริพันธ์'),
 ('ตรวจ ALL-Q10 กับทั้งสอง curl', '∇ × <b>E</b>=−20'+U('z')+'; −μ'+F('∂<b>H</b>','∂t')+'=−μ(2×10<sup>6</sup>)'+U('z')+'<br>μ=10<sup>5</sup> ⇒ ขัดแย้ง; μ=10<sup>−5</sup> ⇒ −20'+U('z'), 'ไฟล์จริงมีเลขชี้กำลัง μ ขัดกับฟาราเดย์ ไม่มี k ที่แก้ได้ทั้งหมด อย่าเลือก k จากแอมแปร์แล้วประกาศว่าสอดคล้อง'),
 ('ค่า k ในฉบับแก้', '∇ × <b>H</b>='+U('x')+'=ε'+F('∂<b>E</b>','∂t')+'=−εk'+U('x')+' ⇒ k=−'+F('1','4×10<sup>−9</sup>')+'=−2.5×10<sup>8</sup> V/(m·s)', 'ต้องแก้ μ เป็น 10⁻⁵ ตาม Hayt D9.4(b) ก่อน แล้วตรวจ divergence D และ B เป็นศูนย์ด้วย')],
 ['อย่านับกระแสการกระจัดว่าเป็นประจุอิสระวิ่งผ่านฉนวน', 'ห้ามคูณพื้นที่ก่อนตรวจว่าทิศและสนามสม่ำเสมอ', 'ALL-Q10 ฉบับต้นฉบับไม่มีค่า k ที่ทำให้ครบทุกสมการ ต้องรายงานข้อขัดแย้ง'],
 ['ตัวเก็บประจุในวงจร AC มี i นำ v อยู่ 90° แม้ฉนวนอุดมคติไม่มีกระแสนำ ความสัมพันธ์มาจากอัตราการเปลี่ยนสนาม ไม่ใช่การรั่ว', 'เมื่อความถี่สูง พจน์นี้สำคัญต่อเสาอากาศและการแพร่พลังงานในฉนวน เป็นสะพานจากการคิดเฉพาะกระแสลวดไปสู่คลื่นแม่เหล็กไฟฟ้า'],
 'ผิวสองผิวที่มีขอบวงเดียวกันตัดผ่านลวดกับฉนวน ต่างให้ยอดกระแสรวมเท่ากันอย่างไร?', 'ตัวเก็บประจุอุดมคติ σ=0 สนามแผ่นขนาน วัสดุคงที่และละเลยสนามขอบ')

lesson(22, [
 'เฟสเซอร์เก็บขนาดและเฟสของสัญญาณที่มีความถี่เดียว แล้วแยกปัจจัยเวลาร่วมออก การแยกนี้ทำให้อนุพันธ์เวลากลายเป็นการคูณ jω แต่ไม่ได้ตัดข้อมูลตำแหน่งออก สนามเชิงอวกาศยังมีเฟสที่เปลี่ยนตาม z',
 'คลื่นเดินทางคือจุดเฟสเดียวกันย้ายตำแหน่งเมื่อเวลาเพิ่ม ถ้าเฟสเป็น ωt−βz คงที่ ต้องเพิ่ม z ตาม t จึงเดิน +z ส่วน E และ H ตั้งฉากกันและตั้งฉากทิศเดินคลื่น พลังงานชี้ตาม E×H',
 'อิมพีแดนซ์คลื่น η เป็นอัตราส่วนขนาด E ต่อ H ในตัวกลาง ไม่ใช่ความต้านทานของลวด อวกาศว่างมีประมาณ 377 Ω การวาด E และ H บนกราฟเดียวต้องระบุว่าปรับสเกล เพราะหน่วยและแอมพลิจูดต่างกัน'], [
 ('นิยามทั่วไปของเฟสเซอร์', '<b>E</b>(<b>r</b>,t)=Re{<b>E</b><sub>s</sub>(<b>r</b>)e<sup>jωt</sup>}', 'เลือกคอนเวนชัน eʲωᵗ และแอมพลิจูด peak ตลอดบท ไม่ผสมกับคอนเวนชันเวลาติดลบหรือ RMS'),
 ('พิสูจน์ตัวดำเนินการเวลา', F('∂','∂t')+'[<b>E</b><sub>s</sub>e<sup>jωt</sup>]=jω<b>E</b><sub>s</sub>e<sup>jωt</sup>', 'เฟสเซอร์ไม่ขึ้นกับ t จึงดึงออกและใช้อนุพันธ์เอ็กซ์โพเนนเชียล หากหลายความถี่ต้องแยกแต่ละความถี่'),
 ('แมกซ์เวลล์ฮาร์มอนิกในฉนวนไร้แหล่ง', '∇ × <b>E</b><sub>s</sub>=−jωμ<b>H</b><sub>s</sub>; ∇ × <b>H</b><sub>s</sub>=jωε<b>E</b><sub>s</sub><br>∇ • <b>E</b><sub>s</sub>=0; ∇ • <b>H</b><sub>s</sub>=0', 'ใช้ σ=0, ρv=0 และ ε,μ คงที่ จึงลดเกาส์ของ D,B เป็น divergence ของ E,H ได้'),
 ('curl อีกครั้งโดยรักษาเครื่องหมาย', '∇ × (∇ × <b>E</b><sub>s</sub>)=−jωμ(∇ × <b>H</b><sub>s</sub>)=−jωμ(jωε<b>E</b><sub>s</sub>)=ω²με<b>E</b><sub>s</sub>', 'j²=−1 ทำให้ลบหน้าและลบจาก j² ตัดกัน ขั้นนี้เชื่อมการเปลี่ยนของสนามทั้งสองเข้าด้วยกัน'),
 ('ใช้เอกลักษณ์เวกเตอร์', '∇ × (∇ × <b>E</b><sub>s</sub>)=∇(∇ • <b>E</b><sub>s</sub>)−∇²<b>E</b><sub>s</sub><br>⇒ ∇²<b>E</b><sub>s</sub>+ω²με<b>E</b><sub>s</sub>=0', 'พจน์ gradient divergence หายเพราะบริเวณไร้ประจุและวัสดุคงที่ ได้สมการคลื่น Helmholtz'),
 ('ลดเป็นหนึ่งมิติและตรวจคำตอบ', F('d²E<sub>xs</sub>','dz²')+'+β²E<sub>xs</sub>=0; β=ω√(με)<br>E<sub>xs</sub>=E<sub>0</sub>e<sup>−jβz</sup> ⇒ '+F('d²E<sub>xs</sub>','dz²')+'=(−jβ)²E<sub>xs</sub>=−β²E<sub>xs</sub>', 'คำตอบทั้ง e⁻ʲᵝᶻ และ eʲᵝᶻ เป็นสองทิศเดินทาง เลือกตามแหล่งและขอบของปัญหา'),
 ('ใช้ฟาราเดย์หา H โดยไม่ข้าม curl', '<b>E</b><sub>s</sub>=E<sub>0</sub>e<sup>−jβz</sup>'+U('x')+'<br>∇ × <b>E</b><sub>s</sub>='+F('∂E<sub>xs</sub>','∂z')+U('y')+'=−jβE<sub>0</sub>e<sup>−jβz</sup>'+U('y')+'=−jωμ<b>H</b><sub>s</sub>', 'สนาม x ที่เปลี่ยนตาม z ให้ curl ตาม y แสดงอนุพันธ์ก่อนตัด −j ทั้งสองข้าง'),
 ('แก้อิมพีแดนซ์และทิศ', '<b>H</b><sub>s</sub>='+F('β','ωμ')+'E<sub>0</sub>e<sup>−jβz</sup>'+U('y')+'='+F('E<sub>0</sub>','η')+'e<sup>−jβz</sup>'+U('y')+'; η=√'+F('μ','ε'), 'β/(ωμ)=√(ε/μ)=1/η ฐาน x×y=z จึงพลังงานเดิน +z'),
 ('ALL-Q11 ความถี่และความยาวคลื่น', 'ω=10<sup>6</sup> rad/s ⇒ f='+F('ω','2π')+'=1.59155×10<sup>5</sup> Hz<br>λ='+F('c','f')+'=1884.96 m; β='+F('ω','c')+'≈3.33333×10<sup>−3</sup> rad/m', 'ใช้ c≈3×10⁸ m/s และ η₀≈120π Ω ร่วมกันเพื่อให้การปัดค่าทั้งข้อสอดคล้องกัน'),
 ('สนามคู่และคืนเวลาจริง', '<b>H</b><sub>s</sub>='+F('250','120π')+'e<sup>−jβz</sup>'+U('y')+'≈0.663146e<sup>−jβz</sup>'+U('y')+' A/m<br><b>H</b>(z,t)=0.663146cos(ωt−βz)'+U('y')+' A/m', 'คงหน่วย A/m และค่า peak ส่วนจริงของผลคูณเอ็กซ์โพเนนเชียลคืนสนามชั่วขณะ'),
 ('ALL-Q12 แยกเวลาแบบออยเลอร์', 'cos(ωt−k<sub>0</sub>z)=Re{e<sup>j(ωt−k₀z)</sup>}=Re{e<sup>−jk₀z</sup>e<sup>jωt</sup>}<br><b>E</b><sub>s</sub>=E<sub>x0</sub>e<sup>−jk₀z</sup>'+U('x')+' V/m', 'ปัจจัยที่ไม่ขึ้นกับ t คือเฟสเซอร์ ถ้าเริ่มจาก sinψ ต้องเขียน cos(ψ−π/2) จึงเพิ่มเฟส −90°'),
 ('ตรวจทิศและพลังงานเฉลี่ย', 'ωt−βz=ค่าคงตัว ⇒ '+F('dz','dt')+'='+F('ω','β')+'>0<br>⟨<b>S</b>⟩='+F('E<sub>0</sub>²','2η')+U('z')+' W/m²', 'ผลคูณ E×H เป็นกำลังต่อพื้นที่เฉลี่ยของคลื่นไร้การสูญเสีย ตัวประกอบครึ่งมาจากค่าเฉลี่ย cos² และใช้แอมพลิจูด peak')],
 ['ω หน่วย rad/s ไม่ใช่ Hz ต้องหาร 2π', 'เฟสเวลาบวกกับตำแหน่งบวกเดิน −z', 'ไม่ใส่ eʲωᵗ ไว้ในเฟสเซอร์ และไม่เปลี่ยน peak เป็น RMS โดยไม่แจ้ง', 'สูตร β=ω√με และ η=√(μ/ε) นี้ใช้กรณีไม่สูญเสีย; ตัวกลางนำต้องใช้ค่าซับซ้อน'],
 ['เสาอากาศเปลี่ยนพลังงานจากกระแสในตัวนำเป็นคลื่นที่พลังงานไหลในอวกาศ การจับคู่ E,H และทิศพลังงานเป็นพื้นฐานของการวัดโพลาไรเซชัน', 'สนามและอิมพีแดนซ์เชื่อมต่อกับสายส่งใน Hayt บท 10 ส่วนคลื่นระนาบอยู่บท 11 การออกแบบการส่งพลังงานต้องรู้ว่ามีทั้งสนาม E และ H แม้ตัวนำเป็นเพียงขอบของบริเวณสนาม'],
 'เมื่อกลับจาก e⁻ʲᵝᶻ เป็น eʲᵝᶻ โดย E ยังตาม x ทิศ H ต้องเปลี่ยนอย่างไรจึง E×H เดิน −z?', 'ความถี่เดียว peak, eʲωᵗ, ตัวกลางเนื้อเดียวเชิงเส้นไร้แหล่ง σ=0 และคลื่นระนาบ')
